(window.MATRIX_DATA_PARTS ||= Object.create(null))["data/poems-0007.js"] = [{"id":"poem-2eb94f01ffad5ba91469c3f5","title":"鼓吹曲辞 有所思","author":"刘氏云","dynasty":"唐","verses":["朝亦有所思，暮亦有所思。","登楼望君处，蔼蔼浮云飞。","浮云遮却阳关道，向晚谁知妾怀抱。","玉井苍苔春院深，桐花落地无人扫。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-ea6c5a06-ed63-49f3-82aa-bb7bbded3ee5","tags":[]},{"id":"poem-2ebcfc19cf441d7d7016e655","title":"七谏·怨思","author":"东方朔","dynasty":"汉","verses":["贤士穷而隐处兮，廉方正而不容。","子胥谏而靡躯兮，比干忠而剖心。","子推自割而飤君兮，德日忘而怨深。","行明白而曰黑兮，荆棘聚而成林。","江离弃于穷巷兮，蒺藜蔓乎东厢。","贤者蔽而不见兮，谗谀进而相朋。","枭鸮并进而俱鸣兮，凤皇飞而高翔。","原壹往而径逝兮，道壅绝而不通。"],"enabled":true,"collection":"楚辞","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/楚辞/chuci.json#record-33","tags":[]},{"id":"poem-2ec22df29b3664288a278ff6","title":"鸳鸯","author":"佚名","dynasty":"先秦","verses":["鸳鸯于飞，毕之罗之。君子万年，福禄宜之。","鸳鸯在梁，戢其左翼。君子万年，宜其遐福。乘马在厩，摧之秣之。君子万年，福禄艾之。","乘马在厩，秣之摧之。君子万年，福禄绥之。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-215","tags":[]},{"id":"poem-2eccb3b036a251112cde20e2","title":"銮驾东回","author":"崔道融","dynasty":"唐","verses":["两川花捧御衣香，万岁山呼辇路长。","天子还从马嵬过，别无惆怅似明皇。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-4973c3cd-702f-470d-abfa-c194e4688dca","tags":[]},{"id":"poem-2ed1fac1a5f612cfe359be44","title":"清平乐·风光紧急","author":"朱淑真","dynasty":"宋","verses":["风光紧急。","三月俄三十。","拟欲留连计无及。","绿野烟愁露泣。","倩谁寄语春宵。","城头画鼓轻敲。","缱绻临歧嘱付，来年早到梅梢。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-868","tags":[]},{"id":"poem-2edeac83747cfdb7d9e94d9b","title":"上卢少卿觅千文","author":"贯休","dynasty":"唐","verses":["荆山有美玉，含华尚炳烂。","堪为圣君玺，堪为圣君案。","草木润不雕，烟霞覆不散。","野人到山下，仰视星辰畔。","倘或如栗黄，保之上霄汉。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-66725f40-86fd-4d39-b906-5bb47a7b5336","tags":[]},{"id":"poem-2ee0c7b74c2064da45a49fac","title":"小宛","author":"佚名","dynasty":"先秦","verses":["宛彼鸣鸠，翰飞戾天。我心忧伤，念昔先人。明发不寐，有怀二人。","人之齐圣，饮酒温克。彼昏不知，一醉日富。各敬尔仪，天命不又。","中原有菽，庶民采之。螟蛉有子，蜾蠃负之。教诲尔子，式谷似之。","题彼脊令，载飞载鸣。我日斯迈，而月斯征。夙兴夜寐，毋忝尔所生。","交交桑扈，率场啄粟。哀我填寡，宜岸宜狱。握粟出卜，自何能谷？","温温恭人，如集于木。惴惴小心，如临于谷。战战兢兢，如履薄冰。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-195","tags":[]},{"id":"poem-2eee1e07734b53058836b47f","title":"偈颂六十七首  其一七","author":"释原妙","dynasty":"宋","verses":["一叶落，天下秋。","一尘起，大地收。","有意气时添意气，不风流处也风流。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-e6db4da0-b1bf-4da7-ba3f-c891b1658492","tags":[]},{"id":"poem-2efb71f1c0019e8c1ad80c44","title":"悬水","author":"陈岩","dynasty":"宋","verses":["日夜云间喷薄鸣，玉龙千尺绕山行。","漏天泻下银河水，来作僧窗夜雨声。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-6e6c3e8b-f828-4149-a0d8-b284de893c77","tags":[]},{"id":"poem-2efcd54c53efd167ea8f7778","title":"临滹沱见蕃使列名","author":"李益","dynasty":"唐","verses":["漠南春色到滹沱，碧柳青青塞马多。","万里关山今不闭，汉家频许郅支和。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-8806295e-05bb-40d8-9776-e4eaeee89d1a","tags":[]},{"id":"poem-2f07800ae1ba9dbd3b3bf47a","title":"四六","author":"王梵志","dynasty":"唐","verses":["恶口深乖礼，条中却没文。","若能不骂詈，即便是贤人。","（「即便是」，伯三七一六卷作「即是大」，伯三六五六卷作「却便是」。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-c94a2244-f51b-46c5-88db-cf1b01607dc0","tags":[]},{"id":"poem-2f0c2d7d34d4f25d91d3c3d1","title":"菩萨蛮·荒鸡再咽天难晓","author":"纳兰性德","dynasty":"清","verses":["荒鸡再咽天难晓，星榆落尽秋将老。","毡幕绕牛羊，敲冰饮酪浆。","山程兼水宿，漏点清钲续。","正是梦回时，拥衾无限思。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-192","tags":[]},{"id":"poem-2f1a46d52395685f9433690d","title":"惜花","author":"刘言史","dynasty":"唐","verses":["年少共怜含露色，老人偏惜委尘红。","如何遂得心中事，每要花时不厌风。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-ba152c85-e889-40b0-812b-2fb34179e18f","tags":[]},{"id":"poem-2f1b5675814fcdaff9d1057a","title":"八声甘州·谓东坡、未老赋归来","author":"晁补之","dynasty":"宋","verses":["谓东坡、未老赋归来，天未遣公归。","向西湖两处秋波一种，飞蔼澄辉。","又拥竹西歌吹，僧老木兰非。","一笑千秋事，浮世危机。","应倚平山栏槛，是醉翁饮处，江雨霏霏。","送孤鸿相接，今古眼中稀。","念平生、相从江海，任飘蓬、不遣此心违。","登临事，更何须惜，吹帽淋衣。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-125","tags":["西湖"]},{"id":"poem-2f302638f6f27dcf19f81afb","title":"点绛唇·明月山头","author":"向子𬤇","dynasty":"宋","verses":["明月山头，古香吹堕青林底。","世情无味。","伴我千岩里。","诗老风流，也向花留意。","歌新拟。","调高难比。","半坐分君醉。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-164","tags":[]},{"id":"poem-2f30fd48919e22f64c5f8563","title":"郊庙歌辞 中宗祀昊天乐章 豫和","author":"不详","dynasty":"唐","verses":["天之历数归睿唐，顾惟菲德钦昊苍。","撰吉日兮表殷荐，冀神鉴兮降闿阳。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-ba51429a-7ee2-44d2-a01f-61013d90419b","tags":[]},{"id":"poem-2f33af735b433b71c9677735","title":"秋晚霁后野望忆夏侯审","author":"卢纶","dynasty":"唐","verses":["天晴禾黍平，畅目亦伤情。","野店云日丽，孤庄砧杵鸣。","川原唯寂寞，岐路自纵横。","前后无俦侣，此怀谁与呈。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-90fc2eea-4a5c-4bca-8720-23c04d7f523d","tags":[]},{"id":"poem-2f39e6a38514afd859e17588","title":"本序","author":"施惠《幽闺记》","dynasty":"元","verses":["(旦)春思恹恹，此愁谁诉，此情谁知；心撩乱，慵睹妆台梳洗。","(小旦)芳时不暖不寒，秋千院宇，堪游堪戏。","(旦)空对莺花燕柳，悄忽地暗皱双眉。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-3056","tags":[]},{"id":"poem-2f3eeb4fdef235a218bf0b8b","title":"明日雨止复招子骏尧夫游南园  其二","author":"司马光","dynasty":"宋","verses":["遥思花寨交横锦，未分春心斗顿灰。","更与二三头白友，试携薄具上高台。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-1e78a72c-f7be-4cd4-be93-4cb3b97161bc","tags":[]},{"id":"poem-2f4e266b1245925350773e35","title":"赠姚合少府","author":"张籍","dynasty":"唐","verses":["病来辞赤县，案上有丹经。","为客烧茶灶，教儿埽竹亭。","诗成添旧卷，酒尽卧空缾。","阙下今遗逸，谁瞻隐士星。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-4f315ed4-b73a-4a9e-8799-98871c553726","tags":[]},{"id":"poem-2f5e961171c54272ae83617f","title":"寄题江山叶氏翠香亭  其四","author":"王柏","dynasty":"宋","verses":["小诗越境论交情，不见新亭句未精。","寄语主人犹缺典，梅花应恨不同清。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-9a0ce6aa-6fcf-4346-8017-ca6ae19b9832","tags":[]},{"id":"poem-2f5f6629a634c14afc9c83fb","title":"孤屿","author":"张又新","dynasty":"唐","verses":["碧水逶迤浮翠𪩘，绿萝蒙密媚晴江。","不知谁与名孤屿，其实中川是一双。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-0c23b2e8-35ba-4933-ad6c-fe0b722dc449","tags":[]},{"id":"poem-2f6147cfba51e30ddc64a126","title":"田母拒金图","author":"丁易东","dynasty":"宋","verses":["噫嘘嚱，人奔奔，皆为名利之所役，贤反愚兮明反昏。","夜却金兮尚高洁，择一钱兮义同颉。","莱芜甑中尘扑飞，悬鱼老子肝似铁。","四公皦皦何不墨，图中但见齐田稷。","蠹吏亏纲勿足夸，特貌慈闱耀贞德。","奉君本欲娱亲喜，阿母怒兮惊且愧。","若使当年一纳间，那得芳名播青史。","主圣亲贤臣涤衷，公金赐妪恩爱隆。","非独舍之罪不诛，昭昭淳化扬仁风。","我披此传重踟蹰，岂独田卿贪若斯。","谓语今人知不知，偷安苟富诚何如。","老万翁，志不渝，费千金，畜此图。","此图传后世，后世重义轻金与。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-77c278a5-696c-4da2-a8f6-7abd850231dd","tags":[]},{"id":"poem-2f682f0089b88d88e9dddb80","title":"游仙词三十三首  其二○","author":"王镃","dynasty":"宋","verses":["偶巡三岛过瀛洲，闲把新绛系海虬。","忽报词臣当直日，灵风吹到五云楼。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-4033a8b9-74d9-4bd8-8588-81b79420671a","tags":[]},{"id":"poem-2f6c6f421b215d7e0987ef5d","title":"和东园黄香梅之作因复劝游","author":"綦崇礼","dynasty":"宋","verses":["寒梅残几枝，插花无点髪。","僧房不得地，飘零人所忽。","谿风晚来急，寻香堆碎月。","不料东城春，娇黄方秀发。","新诗寓佳赏，留情宁一物。","芳卉满春山，篮舆来莫歇。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-3badda9f-29b3-4f96-a356-5fb3afba43c2","tags":[]},{"id":"poem-2f6f1580cf1e6345d984770f","title":"哭程晦夫  其一","author":"孙嵩","dynasty":"宋","verses":["握手论交意气真，旧游四顾暗伤神。","陪从金马门中客，和唱铜驼陌上春。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-f58c54d7-9497-4a48-9cdc-69045d9768a6","tags":[]},{"id":"poem-2f7489e35044bb0ea9817224","title":"宿茅山寄舍弟","author":"徐铉","dynasty":"宋","verses":["茅许禀灵气，一家同上宾。","仙山空有庙，举世更无人。","独往诚违俗，浮名亦累真。","当年各自勉，云洞镇长春。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-4d5d84c3-3521-433a-ade8-4b13da146199","tags":[]},{"id":"poem-2f749b93039da1f59e34793a","title":"雨","author":"杜甫","dynasty":"唐","verses":["行云递崇高，飞雨霭而至。","潺潺石间溜，汩汩松上驶。","亢阳乘秋热，百谷皆已弃。","皇天德泽降，焦卷有生意。","前雨伤卒暴，今雨喜容易。","不可无雷霆，间作鼓增气。","佳声达中宵，所望时一致。","清霜九月天，髣髴见滞穗。","郊扉及我私，我圃日苍翠。","恨无抱瓮力，庶减临江费。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-24f9e8b4-e32d-49e7-af89-50e05880b662","tags":[]},{"id":"poem-2f7aff191a25e007b4090457","title":"寄安抚曹观使  其二","author":"释居简","dynasty":"宋","verses":["筼筜抱节癯，风味似楼居。","自是宦情薄，容教杯酒疎。","扫除新筑室，收拾旧观书。","何必陶元亮，斜阳自荷鉏。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-9d428a14-3641-472c-a536-906cfc235901","tags":[]},{"id":"poem-2f836e75b44ff23438368f0a","title":"贺新郎·绿树听鹈","author":"辛弃疾","dynasty":"宋","verses":["绿树听鹈。","更那堪、鹧鸪声住，杜鹃声切。","啼到春归无寻处，苦恨芳菲都歇。","算未抵、人间离别。","马上琵琶关塞黑，更长门、翠辇辞金阙。","看燕燕，送归妾。","将军百战身名裂。","向河梁、回头万里，故人长绝。","易水萧萧西风冷，满座衣冠似雪。","正壮士、悲歌未彻。","啼鸟还知如许恨，料不啼清泪长啼血。","谁共我，醉明月。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-216","tags":["宋词三百首"]},{"id":"poem-2f8424f9ae6b124c01fad06e","title":"送德清卫明府赴选","author":"皎然","dynasty":"唐","verses":["八使慎求能，东人独荐君。","身犹千里限，名已九霄闻。","远路翻喜别，离言暂惜分。","凤门多士会，拥佩入卿云。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-86bc6eb7-4e17-4174-9a17-877b3f6b8dbd","tags":[]},{"id":"poem-2f8edcb4e088946291f9a244","title":"送著作佐郎崔融等从梁王东征","author":"陈子昂","dynasty":"唐","verses":["金天方肃杀，白露始专征。","王师非乐战，之子慎佳兵。","海气侵南部，边风扫北平。","莫卖卢龙塞，归邀麟阁名。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-送著作佐郎崔融等從樑王東征","tags":[]},{"id":"poem-2f9149e3345e555b7fbabfb7","title":"小游仙诗九十八首 九十五","author":"曹唐","dynasty":"唐","verses":["新授金书八素章，玉皇教妾主扶桑。","与君一别三千岁，却厌仙家日月长。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-e58c5aea-de33-48ed-822f-b716bf2c0732","tags":[]},{"id":"poem-2f9f635dfbf8e42ed60b2752","title":"次韵郭梅边汤孤松见寄","author":"赵文","dynasty":"宋","verses":["杜门却扫冯敬通，何人载酒暖此翁。","昼长书罢啼鸟寂，山水似我清而穷。","山僧携来两诗卷，笔势迅疾如追锋。","渔歌风断郭功父，碧云暮合汤休公。","寒梅自照太古雪，孤松压倒妖春红。","一时见此光怪物，丈室忽换化人宫。","近者重游宝林寺，山行小辟炎毒攻。","唱酬坐觉山鬼泣，谈笑不知酒海空。","当时分韵十五客，冠童亦有童非童。","惜哉梅松不在眼，自与修竹为吾宗。","传闻浄觉更殊胜，极欲往求三日聋。","补天久已付昨梦，面壁更欲收奇功。","百年金碧亦尘土，须有好语留山中。","山中道人许我否，饱饭摩腹听松风。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-153c9edb-41d2-431c-9c4e-2a5863a75c72","tags":[]},{"id":"poem-2fa97fa1ca98493671d0042e","title":"驩州南亭夜望","author":"沈佺期","dynasty":"唐","verses":["昨夜南亭望，分明梦洛中。","室家谁道别，儿女案尝同。","忽觉犹言是，沈思始悟空。","肝肠余几寸，拭泪坐春风。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-40d32391-64e6-4c4c-bc8b-61cbe581b6da","tags":[]},{"id":"poem-2fb29d2e268d3dd5b3906946","title":"开先寺观瀑布","author":"米芾","dynasty":"宋","verses":["度挟扪青玉，临深坐绿苔。","水从双剑下，山挟两龙来。","春暖花惊雪，林空石迸雷。","尘缨聊此濯，欲去首重回。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-d4c49cef-c9f2-4b1f-9b24-5b905b41f110","tags":[]},{"id":"poem-2fb7d8794983279d267b3394","title":"宿凤翔天柱寺穷易玄上人房","author":"李洞","dynasty":"唐","verses":["天柱暮相逢，吟思天柱峰。","墨研青露月，茶吸白云钟。","卧语身黏藓，行禅顶拂松。","探玄为一决，明日去临邛。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-de2bfa12-cd5f-41e3-859d-af38ed2d3b34","tags":[]},{"id":"poem-2fbf6057142603b6d942769a","title":"一江风","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["绣房中，袅袅香烟喷，翦翦轻风送；但晨昏问寝高堂，须把椿萱奉。","忙梳早整容，忙梳早整容，惟勤针指功，怕窗外花影日移动。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8075","tags":[]},{"id":"poem-2fd07f5c5c6e4008f22a501a","title":"诉衷情·冷落绣衾谁与伴","author":"纳兰性德","dynasty":"清","verses":["冷落绣衾谁与伴，倚香篝。","春睡起，斜日照梳头。","欲写两眉愁，休休。","远山残翠收，莫登楼。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-52","tags":[]},{"id":"poem-2fda30d638084ab6b66fd740","title":"焦山普济禅院碑赞","author":"米芾","dynasty":"宋","verses":["古佛留法度大心，种种威摄现胜相。","大心众生摄威德，求度倾身及众宝。","冥阳咸会精诚通，正法是归大缘集。","我今稽首佛陀僧，永奠海山作津筏。","我今稽首明应公，永护宝车炳威德。","悉化大心依浄住，一世咸如今佛日。","三光不愆四序调，主圣臣忠载万亿。","五谷蕃生土地肥，万灵常跻仁寿域。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-e9136b48-ad39-42d3-a142-142749fc5c3e","tags":[]},{"id":"poem-2fe3ffe2fb52eb054da4a030","title":"九叹·远游","author":"刘向","dynasty":"汉","verses":["悲余性之不可改兮，屡惩艾而不迻。","服觉皓以殊俗兮，貌揭揭以巍巍。","譬若王侨之乘云兮，载赤霄而凌太清。","欲与天地参寿兮，与日月而比荣。","登昆仑而北首兮，悉灵圉而来谒。","选鬼神于太阴兮，登阊阖于玄阙。","回朕车俾西引兮，褰虹旗于玉门。","驰六龙于三危兮，朝西灵于九滨。","结余轸于西山兮，横飞谷以南征。","绝都广以直指兮，历祝融于朱冥。","枉玉衡于炎火兮，委两馆于咸唐。","贯澒蒙以东朅兮，维六龙于扶桑。","周流览于四海兮，志升降以高驰。","征九神于回极兮，建虹采以招指。","驾鸾凤以上游兮，从玄鹤与鹪明。","孔鸟飞而送迎兮，腾群鹤于瑶光。","排帝宫与罗囿兮，升县圃以眩灭。","结琼枝以杂佩兮，立长庚以继日。","凌惊雷以轶骇电兮，缀鬼谷于北辰。","鞭风伯使先驱兮，囚灵玄于虞渊。","溯高风以低佪兮，览周流于朔方。","就颛顼而敶辞兮，考玄冥于空桑。","旋车逝于崇山兮，奏虞舜于苍梧。","济杨舟于会稽兮，就申胥于五湖。","见南郢之流风兮，殒余躬于沅湘。","望旧邦之黯黮兮，时溷浊其犹未央。","怀兰茝之芬芳兮，妒被离而折之。","张绛帷以襜襜兮，风邑邑而蔽之。","日暾暾其西舍兮，阳焱焱而复顾。","聊假日以须臾兮，何骚骚而自故。","叹曰：譬彼蛟龙乘云浮兮，泛淫澒溶纷若雾兮。","潺湲𫐖轕雷动电发馺高举兮。","升虚凌冥沛浊浮清入帝宫兮，摇翘奋羽驰风骋雨游无穷兮。"],"enabled":true,"collection":"楚辞","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/楚辞/chuci.json#record-55","tags":[]},{"id":"poem-2fed7a170b15dd7452d5dc92","title":"曲江渔父","author":"李洞","dynasty":"唐","verses":["儿孙闲弄雪霜髯，浪飐南山影入簷。","卧稳篷舟龟作枕，病来茅舍网为帘。","值春游子怜莼滑，通蜀行人说鲙甜。","数尺寒丝一竿竹，岂知浮世有猜嫌。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-0919bd54-20f4-4c8d-8c8b-f162de3dac9a","tags":[]},{"id":"poem-3002f4e4eeebcb4841fdf956","title":"红衲袄","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["［外］问：古人君所以贤，古人臣所可言，圣王汲汲思为善，为善还当何者先？子辈灯窗已有年，所得经书学问渊。","悉心为我敷陈也，毋视庸常泛泛然。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8044","tags":[]},{"id":"poem-3004793d6652fbe829e9298f","title":"虞美人·碧梧桐映纱窗晚","author":"顾敻","dynasty":"五代","verses":["碧梧桐映纱窗晚，花谢莺声懒。","小屏屈曲掩青山，翠帷香粉玉炉寒，两蛾攒。","颠狂少年轻离别，辜负春时节。","画罗红袂有啼痕，魂消无语倚闺门，欲黄昏。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-6-juan.json#record-36","tags":[]},{"id":"poem-300c1ad664fb83e2ba29e5af","title":"劝人 二十二","author":"义存","dynasty":"唐","verses":["报汝等知乎，真性不在途。","色身祇要闲，何用苦区区。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-a6c80aeb-b9e4-4c7a-8c1e-8df347ed6736","tags":[]},{"id":"poem-300d8e39f94ec9975cebb032","title":"远游","author":"屈原","dynasty":"先秦","verses":["悲时俗之迫阨兮，愿轻举而远游。","质菲薄而无因兮，焉讬乘而上浮？","遭沈浊而污秽兮，独郁结其谁语！","夜耿耿而不寐兮，魂营营而至曙。","惟天地之无穷兮，哀人生之长勤。","往者余弗及兮，来者吾不闻。","步徙倚而遥思兮，怊惝怳而乖怀。","意荒忽而流荡兮，心愁凄而增悲。","神倏忽而不反兮，形枯槁而独留。","内惟省以操端兮，求正气之所由。","漠虚静以恬愉兮，澹无为而自得。","闻赤松之清尘兮，愿承风乎遗则。","贵真人之休德兮，美往世之登仙。","与化去而不见兮，名声著而日延。","奇傅说之讬辰星兮，羡韩众之得一。","形穆穆以浸远兮，离人群而遁逸。","因气变而遂曾举兮，忽神奔而鬼怪。","时仿佛以遥见兮，精晈晈以往来。","超氛埃而淑邮兮，终不反其故都。","免众患而不惧兮，世莫知其所如。","恐天时之代序兮，耀灵晔而西征。","微霜降而下沦兮，悼芳草之先蘦。","聊仿佯而逍遥兮，永历年而无成。","谁可与玩斯遗芳兮？","长向风而舒情。","高阳邈以远兮，余将焉所程？","重曰：春秋忽其不淹兮，奚久留此故居。","轩辕不可攀援兮，吾将从王乔而娱戏。","餐六气而饮沆瀣兮，漱正阳而含朝霞。","保神明之清澄兮，精气入而麤秽除。","顺凯风以从游兮，至南巢而壹息。","见王子而宿之兮，审壹气之和德。","曰“道可受兮，不可传。","其小无内兮，其大无垠。","毋滑而魂兮，彼将自然。","壹气孔神兮，于中夜存。","虚以待之存，无为之先。","庶类以成兮，此德之门。”","闻至贵而遂徂兮，忽乎吾将行。","仍羽人于丹丘，留不死之旧乡。","朝濯发于汤谷兮，夕晞余身兮九阳。","吸飞泉之微液兮，怀琬琰之华英。","玉色頩以脕颜兮，精醇粹而始壮。","质销铄以汋约兮，神要眇以淫放。","嘉南州之炎德兮，丽桂树之冬荣。","山萧条而无兽兮，野寂漠其无人。","载营魄而登霞兮，掩浮云而上征。","命天阍其开关兮，排阊阖而望予。","召丰隆使先导兮，问太微之所居。","集重阳入帝宫兮，造旬始而观清都。","朝发轫于太仪兮，夕始临乎于微闾。","屯余车之万乘兮，纷容与而并驰。","驾八龙之婉婉兮，载云旗之逶蛇。","建雄虹之采旄兮，五色杂而炫耀。","服偃蹇以低昂兮，骖连蜷以骄骜。","骑胶葛以杂乱兮，斑漫衍而方行。","撰余辔而正策兮，吾将过乎句芒。","历太皓以右转兮，前飞廉以启路。","阳杲杲其未光兮，凌天地以径度。","风伯为余先驱兮，氛埃辟而清凉。","凤凰翼其承旗兮，遇蓐收乎西皇。","揽慧星以为旍兮，举斗柄以为麾。","叛陆离其上下兮，游惊雾之流波。","时暧曃其曭莽兮，召玄武而奔属。","后文昌使掌行兮，选署众神以并毂。","路漫漫其修远兮，徐弭节而高厉。","左雨师使径侍兮，右雷公以为卫。","欲度世以忘归兮，意姿睢以抯挢。","内欣欣而自美兮，聊媮娱以淫乐。","涉青云以泛滥游兮，忽临睨夫旧乡。","仆夫怀余心悲兮，边马顾而不行。","思旧故以想象兮，长太息而掩涕。","汜容与而遐举兮，聊抑志而自弭。","指炎神而直驰兮，吾将往乎南疑。","览方外之荒忽兮，沛罔瀁而自浮。","祝融戒而跸御兮，腾告鸾鸟迎宓妃。","张咸池奏承云兮，二女御九韶歌。","使湘灵鼓瑟兮，令海若舞冯夷。","玄螭虫象并出进兮，形蟉虬而逶蛇。","雌蜺便娟以增挠兮，鸾鸟轩翥而翔飞。","音乐博衍无终极兮，焉乃逝以徘徊。","舒并节以驰骛兮，逴绝垠乎寒门。","轶迅风于清源兮，从颛顼乎增冰。","历玄冥以邪径兮，乘间维以反顾。","召黔赢而见之兮，为余先乎平路。","经营四方兮，周流六漠。","上至列缺兮，降望大壑。","下峥嵘而无地兮，上寥廓而无天。","视倏忽而无见兮，听惝恍而无闻。","超无为以至清兮，与泰初而为邻。"],"enabled":true,"collection":"楚辞","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/楚辞/chuci.json#record-22","tags":[]},{"id":"poem-30104b21e74f3838a7bec445","title":"四气","author":"雍裕之","dynasty":"唐","verses":["春禽犹竞啭，夏木忽交阴。","稍觉秋山远，俄惊冬霰深。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-3bbe8c32-7aa3-4820-afb3-58d2cbaac62d","tags":[]},{"id":"poem-3014dc22bf0085590509a215","title":"分韵得两字","author":"王十朋","dynasty":"宋","verses":["官舍苦炎热，贡闱快虚敞。","急呼玉友生，闲共同僚赏。","堂成桂植万，堤就池分两。","莲开花并蒂，荔擘珠在掌。","诗句听细论，尘襟发清爽。","行矣北归翁，山林起遥想。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-80ab8cf7-7c5c-4ffa-8fe8-b28b0f3bff0b","tags":[]},{"id":"poem-30167409a69bbf4cc24773c2","title":"句  其五","author":"孟宾于","dynasty":"宋","verses":["因逢日者教重应，忍被云僧劝却归。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-ba696aa6-7030-429b-b3ba-4db36ffcebaf","tags":[]},{"id":"poem-301b6fb20fa6396bf39db573","title":"兵要望江南 禳厌第二十四（京本作「占厌禳第十九」○十三首） 四","author":"易静","dynasty":"唐","verses":["军行日，秋始与秋分。","金气旺时须要顺，先持弓矢向前行（京本作「存」），得胜远方闻。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-a07ad083-e681-42d9-94e7-16989ec4453c","tags":[]},{"id":"poem-30293c7af64fcae316d8e195","title":"凤凰台忆吹箫・凤凰台上忆吹箫·水国云乡","author":"权无染","dynasty":"宋","verses":["水国云乡，冰魂雪魄，朝来新领春还。","便未怕、天暄蜂蝶，笛转羌蛮。","一树垂云似画，香暗暗、白浅红班。","东风外，清新雪月，潇洒溪山。","应是飞琼弄玉，天不管、年年谪向人间。","占芳事，铅华一洗，红叶俱残。","多少烟愁雨恨，空脉脉、意远情闲。","无人见，翠袖倚竹天寒。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-865","tags":[]},{"id":"poem-303528317205618e3666f0e5","title":"十二咏 花坞","author":"李纲","dynasty":"宋","verses":["收拾群英赖化工，嫣然红紫自成丛。","四时不绝芳菲意，谁谓春归阆苑中。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-a18a4c5e-0ace-4478-8b3d-15fc24c06f89","tags":[]},{"id":"poem-303b4a2384db9f76a4efb8ae","title":"草鞋夹","author":"陈造","dynasty":"宋","verses":["隆岸围小河，纡鬰江之隩。","初看一泓窄，旋望百顷渌。","艅艎与下濑，山屹复云矗。","自治贵不试，此舟江左腹。","向来胡骑南，势若撼坤轴。","飞城截中流，群孽颈为缩。","元凶坐自毙，犬羊仅还毂。","千龄有机会，二竖方角逐。","武刚环貔貅，突骑骛陵陆。","古今常胜术，所投副所欲。","神州久望望，庙算伫复复。","区区计自保，胶柱难为曲。","客行宁贾胡，小泊遂信宿。","抚事空三叹，为儒惭碌碌。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-44318f50-b333-496e-be5c-60b52ce16d4c","tags":[]},{"id":"poem-303bd7cd3c046296ece28da5","title":"少仪","author":"司空图","dynasty":"唐","verses":["昨日登班缀柏台，更惭起草属微才。","锦窠不是寻常锦，兼向丘迟夺得来。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-19a00417-968f-41c2-87d2-ba89c05b5058","tags":[]},{"id":"poem-303f8eb4a18ee2fff6fdcf85","title":"句  其七","author":"司马光","dynasty":"宋","verses":["蝉声若唤人。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-e32b3b17-2ae2-42de-9a93-543330530185","tags":[]},{"id":"poem-30407b3f71b0e701789e70b7","title":"梅花","author":"林逋","dynasty":"宋","verses":["众芳摇落独鲜妍，占断风情向小园。","疏影横斜水清浅，暗香浮动月黄昏。","霜禽欲下先偷眼，粉蝶如知合断魂。","幸有微吟可相狎，不须檀板共金樽。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-梅花","tags":[]},{"id":"poem-3044ddbe804cae55eb8b08f2","title":"今上初登极岁送皇甫孝廉赴选","author":"皎然","dynasty":"唐","verses":["行应会府春，欲劝及芳辰。","北极天文正，东风汉律新。","少年逢圣代，欢笑别情亲。","况是勋庸后，恩荣袭尔身。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-7c60e0bd-891b-41da-8db2-3091534cd6b8","tags":[]},{"id":"poem-304bffa9e2e842065f08cb80","title":"山居诗  其五四","author":"释延寿","dynasty":"宋","verses":["万般惟道最堪依，一瞬荣枯万古悲。","强笑低颜何忽忽，忘机绝虑自怡怡。","潜龙终要投深浦，巢鸟应须占健枝。","名利门中难立足，隠藏云水更何之。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-6cb35d7c-0ad9-4b24-8642-0afb38786d3f","tags":[]},{"id":"poem-304d2a15f09abdeff2f2454e","title":"题城南书院三十四咏  其三○","author":"张栻","dynasty":"宋","verses":["睡觉西山月正平，荷香不断晓凉生。","园中只鹤知人意，已作金风警露声。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-71d3a196-44b0-4f5a-b9c9-eea38e0626dd","tags":[]},{"id":"poem-3053e0404864891b8fd1028f","title":"赠陈正字","author":"赵嘏","dynasty":"唐","verses":["鲁儒今日意何如，名挂春官选籍初。","野艇几曾寻水去，故山从此与云疎。","吟怜受露花阴足，行觉嘶风马力余。","闻说晚心心更静，竹间依旧卧看书。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-e6331512-d4a6-4822-889b-7e3688aa4999","tags":[]},{"id":"poem-3056561356a6f05cb99ac686","title":"杂兴六首 四","author":"皎然","dynasty":"唐","verses":["独高庭中鹤，意远贵氛埃。","有时青冥游，顾我还下来。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-ee47c307-2b14-4a7f-b10b-3ec948ad6c32","tags":[]},{"id":"poem-3068e54e6101c7933b4d4b97","title":"渔家傲·幽鹭慢来窥品格","author":"晏殊","dynasty":"宋","verses":["幽鹭慢来窥品格。","双鱼岂解传消息。","绿柄嫩香频采摘。","心似织。","条条不断谁牵役。","粉泪暗和清露滴。","罗衣染尽秋江色。","对面不言情脉脉。","烟水隔。","无人说似长相忆。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-520","tags":[]},{"id":"poem-307795647e0e818216f62860","title":"春秋战国门 再吟","author":"周昙","dynasty":"唐","verses":["攻城来下惜先分，一旦家邦属四邻。","徒逞威强称智伯，不知权变是愚人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-7d2fafc2-8879-43b7-b338-119a268ad929","tags":[]},{"id":"poem-308031d8337626f147a38965","title":"答人","author":"太上隐者","dynasty":"唐","verses":["偶来松树下，高枕石头眠。","山中无历日，寒尽不知年。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-答人","tags":[]},{"id":"poem-308ccd63121dc4e7c06ce799","title":"郊庙歌辞 德明兴圣庙乐章 兴圣酌献","author":"李舒","dynasty":"唐","verses":["閟宫静谧，合乐周张。","泰尊始献，百末重觞。","震澹存诚，庶几迪尝。","遥源之祚，天汉灵长。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-b254f983-1f0a-40c9-9a35-19d1699fb83b","tags":[]},{"id":"poem-308eef657e3c52a3ac82c1b7","title":"郊庙歌辞 太清宫乐章 煌煌","author":"不详","dynasty":"唐","verses":["煌煌道宫，肃肃太清。","礼光尊祖，乐备充庭。","罄竭诚至，希夷降灵。","云凝翠盖，风燄红旌。","众真以从，九奏初迎。","永惟休祐，是锡和平。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-fe138730-cbf4-45ab-9763-ed22317873a9","tags":[]},{"id":"poem-3098ba7bda45e4539e1ae904","title":"送杨郎中唐员外奉使湖南","author":"徐铉","dynasty":"宋","verses":["江边微雨柳条新，握节含香二使臣。","两绶对悬云梦日，方舟齐泛洞庭春。","今朝草木逢新律，昨日山川满战尘。","同是多情怀古客，不妨为赋吊灵均。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-9e056811-da44-4da5-b91e-510979a88da3","tags":["洞庭湖"]},{"id":"poem-309dc27b226c8b050b3f62b9","title":"送王涣之彦舟","author":"米芾","dynasty":"宋","verses":["集英春殿鸣鞘歇，神武天临光下澈。","鸿胪初唱第一声，白面王郎年十八。","神武乐育天下造，不使敲抨使传道。","衣锦东南第一州，棘璧湖山两清照。","襄阳野老渔竿客，不爱纷华爱泉石。","相逢不约约无逆，舆握古书同岸帻。","淫朋嬖党初相慕，濯发洒心求易虑。","翩翩辽鹤云中侣，土苴尪鸱那一顾。","迩来器业何深至，湛湛具区无底沚。","可怜一点终不易，枉驾殷勤寻漫仕。","漫仕平生四方走，多与英才并肩肘。","少有俳辞能骂鬼，老学鸱夷漫存口。","一官聊具三径资，取舍殊涂莫回首。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-a6bc0ff4-b8a4-4443-bcdf-a091356b316d","tags":[]},{"id":"poem-30a40d55b51cef151d5f52fd","title":"句","author":"高骈","dynasty":"唐","verses":["。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-5321fbf7-e8e5-4458-a12d-8627f8a94d53","tags":[]},{"id":"poem-30a955af7f7c568dff323205","title":"题宛陵张待举曲肱亭","author":"林之奇","dynasty":"宋","verses":["仲蔚蓬蒿宅，宜城诗句中。","人贤忘巷陋，境胜失途穷。","寒葅书万卷，零乱刚直胸。","偃蹇勋业外，啸歌山水重。","晨鸡催不起，拥被听松风。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-391b92f0-2f34-47ff-a122-a7529002e07f","tags":[]},{"id":"poem-30aa5e8c15422ad673f987a4","title":"葛生","author":"佚名","dynasty":"先秦","verses":["葛生蒙楚，蔹蔓于野。予美亡此，谁与？独处？","葛生蒙棘，蔹蔓于域。予美亡此，谁与？独息？","角枕粲兮，锦衾烂兮。予美亡此，谁与？独旦？","夏之日，冬之夜。百岁之后，归于其居。","冬之夜，夏之日。百岁之后，归于其室。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-123","tags":[]},{"id":"poem-30b49480ef0e3cb2251920d5","title":"同前","author":"无名氏《张协状元》","dynasty":"元","verses":["伊回京阙，没一日暂时得少歇，织素织缣不宁贴。","这般时运，这般恶岁月。","(合同前)(净)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2687","tags":[]},{"id":"poem-30b6fc69b729386373937389","title":"送侍左秘书高疏寮得处州  其一","author":"释居简","dynasty":"宋","verses":["一水分吴越，幽思可得分。","软红援汩汩，坚白扫纭纭。","富卷投囊草，芳余辟蠹芸。","傍池双宿鹭，留得水边云。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-d9a9e389-4176-4ce6-918e-507c08750755","tags":[]},{"id":"poem-30b7e110b563801eb9b99d1b","title":"绿头鸭・多丽·新秋近","author":"晁补之","dynasty":"宋","verses":["新秋近，晋公别馆开筵。","喜清时、衔杯乐圣，未饶绿野堂边。","绣屏深、丽人乍出，坐中雷雨起鹍弦。","花暖间关，冰凝幽咽，宝钗摇动坠金钿。","未弹了、昭君遗怨，四坐已凄然。","西风里、香街驻马，嬉笑微传。","算从来、司空惯，断肠初对云鬟。","夜将阑、井梧下叶，砌蛩收响悄林蝉。","赖得多愁，浔阳司马，当时不在绮筵前。","竞叹赏、檀槽倚困，沈醉到觥船。","芳春调、红英翠萼，重变新妍。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-222","tags":[]},{"id":"poem-30b9ceeba07e991eb2b6e488","title":"好事近·羁旅转飞蓬","author":"赵鼎","dynasty":"宋","verses":["羁旅转飞蓬，投老未知休息。","却念故园春事，舞残红飞雪。","危楼高处望天涯，云海寄穷发。","只有旧时凉月，照清伊双阙。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-969","tags":[]},{"id":"poem-30c5905351ac63bc5911900b","title":"奉酬陆使君见过各赋院中一物得江蓠","author":"皎然","dynasty":"唐","verses":["江蓠生古砌，花每落禅床。","嘉客未采掇，空门自馨香。","名因诗目见，色对道心忘。","不遇陆内史，谁知殊众芳。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-77ee5e3c-0aea-4164-b277-091b9534e0aa","tags":[]},{"id":"poem-30cf5ef02ae4d42be76a6ac8","title":"寒食","author":"释居简","dynasty":"宋","verses":["才见茅簷插柳条，便知寒食是今朝。","春应不恨相寻晚，应恨常阴一半消。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-c047156c-f935-4695-b8e1-15868d9fac30","tags":[]},{"id":"poem-30d14965e5024cb921f21b48","title":"水龙吟·雨馀叠𪩘浮空","author":"韩元吉","dynasty":"宋","verses":["雨馀叠𪩘浮空，望中秀色仙都是。","洞天未锁，人间春老，玉妃曾坠。","锦瑟繁弦，凤箫清响，九霄歌吹。","问分香旧事，刘郎去后，知谁伴、风前醉。","回首暝烟千里。","但纷纷、落红如泪。","多情易老，青鸾何许，诗成谁寄。","斗转参横，半帘花影，一溪寒水。","怅飞凫路杳，行云梦断，有三峰翠。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-845","tags":[]},{"id":"poem-30d2071d49df9c12eb762bce","title":"贾客","author":"苏拯","dynasty":"唐","verses":["长帆挂短舟，所愿疾如箭。","得丧一惊飘，生死无良贱。","不谓天不祐，自是人苟患。","尝言海利深，利深不如浅。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-c1ee0ff4-7f70-4dab-a4f7-a20f32cadd13","tags":[]},{"id":"poem-30d57036b52c10932e1a6db1","title":"临江仙·巍峨万丈与天高","author":"邢俊臣","dynasty":"宋","verses":["巍峨万丈与天高。","物轻人意重，千里送鹅毛。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-838","tags":[]},{"id":"poem-30dc29cea634b2adaf31764c","title":"偶题二首 二","author":"来鹄","dynasty":"唐","verses":["水边箕踞静书空，欲解愁肠酒不浓。","可惜青天好雷雹，只能驱趂懒蛟龙。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-a60d0ee3-d3f3-44ed-87c3-d1c60ce06cb5","tags":[]},{"id":"poem-30dceceea75dd39f6b92baab","title":"积雨","author":"释居简","dynasty":"宋","verses":["积雨低田欲再车，经旬湿稼糵寒沙。","绝怜百念如焦谷，大浸稽天不复芽。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-b15f890c-53ea-40c6-a8b2-7884fae15624","tags":[]},{"id":"poem-30e7d3247b93cce1fe43ef1f","title":"送新罗法师还国","author":"孙逖","dynasty":"唐","verses":["异域今无外，高僧代所稀。","苦心归寂灭，宴坐得精微。","持钵何年至，传灯是日归。","上卿挥别藻，中禁下禅衣。","海阔杯还度，云遥锡更飞。","此行迷处所，何以慰虔祈。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-dc8e091b-eb56-45e2-8089-d508fa1a6aaa","tags":[]},{"id":"poem-30e9721cf9fc2b660d46df29","title":"汉广","author":"佚名","dynasty":"先秦","verses":["南有乔木，不可休息。汉有游女，不可求思。汉之广矣，不可泳思。江之永矣，不可方思。","翘翘错薪，言刈其楚。之子于归，言秣其马。汉之广矣，不可泳思。江之永矣，不可方思。","翘翘错薪，言刈其蒌。之子于归。言秣其驹。汉之广矣，不可泳思。江之永矣，不可方思。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-8","tags":[]},{"id":"poem-30eed6923eeb0fd9bb636972","title":"诉衷情·出林杏子落金盘","author":"周邦彦","dynasty":"宋","verses":["出林杏子落金盘。","齿软怕尝酸。","可惜半残青紫，犹有小唇丹。","南陌上，落花闲。","雨斑斑。","不言不语，一段伤春，都在眉间。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-402","tags":[]},{"id":"poem-30f2478dc53015508ba08cc7","title":"寄新定桂雍","author":"贯休","dynasty":"唐","verses":["独自住乌龙，应怜是衲僧。","句须人未道，君此事偏能。","坞湿云埋观，溪寒月照罾。","相思不可见，江上立腾腾。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-7ac5f2fa-46a7-4b33-bd8b-13100b40e885","tags":[]},{"id":"poem-30f869bff629c8ce226a29fb","title":"与僧话旧","author":"于邺","dynasty":"唐","verses":["草堂前有山，一见一相宽。","处世贵僧静，青松因岁寒。","他山逢旧侣，尽日话长安。","所以闲行迹，千回绕药栏。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-93b4e474-c248-4da8-a1c1-e02c989b0d19","tags":[]},{"id":"poem-310146f2ae35e51548e34c49","title":"句  其六","author":"米芾","dynasty":"宋","verses":["手摩一丈石，读尽上元碑。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-a976e7d6-a808-44a9-a46c-4faaee7181bf","tags":[]},{"id":"poem-311da6235aa090dc4f742365","title":"送别","author":"王维","dynasty":"唐","verses":["山中相送罢，日暮掩柴扉。","春草明年绿，王孙归不归。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-c8a4faa6-8666-44f9-b4c9-df78d7af844d","tags":["唐诗三百首","五言绝句","送别","友情"]},{"id":"poem-3123b20fbedce9506f2dbfaf","title":"玉楼春·湖边柳外楼高处","author":"欧阳修","dynasty":"宋","verses":["湖边柳外楼高处。","望断云山多少路。","阑干倚遍使人愁，又是天涯初日暮。","轻无管系狂无数。","水畔花飞风里絮。","算伊浑似薄情郎，去便不来来便去。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-689","tags":[]},{"id":"poem-31276a43626acf4dc52803ac","title":"水调歌头·斜阳明薄暮","author":"王之道","dynasty":"宋","verses":["斜阳明薄暮，暗雨霁凉秋。","弱云狼藉，晚来风起，席卷更无留。","天外老蟾高挂，皎皎寒光照水，金璧共沈浮。","宾主一时杰，倾动庾公楼。","渡银汉，漙玉露，势欲流。","不妨吟赏，坐拥红袖舞还讴。","暗祝今宵素魄，助我清才逸气，稳步上瀛洲。","欲识瀛洲路，雄据六鳌头。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-139","tags":[]},{"id":"poem-3127f9768ad5c548331f76cd","title":"浣溪沙·碧玉冠轻袅燕钗","author":"毛熙震","dynasty":"五代","verses":["碧玉冠轻袅燕钗，捧心无语步香阶，缓移弓底绣罗鞋。","暗想欢娱何计好，岂堪期约有时乖，日高深院正忘怀。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-9-juan.json#record-38","tags":[]},{"id":"poem-3128f8b000f351ead8311c3b","title":"渔家傲·叶有清风花有露","author":"欧阳修","dynasty":"宋","verses":["叶有清风花有露。","叶笼花罩鸳鸯侣。","白锦顶丝红锦羽。","莲女妒。","惊飞不许长相聚。","日脚沈红天色暮。","青凉伞上微微雨。","早是水寒无宿处。","须回步。","枉教雨里分飞去。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-653","tags":[]},{"id":"poem-31322c57f5667309be1a7e50","title":"送南陵尉李频","author":"张乔","dynasty":"唐","verses":["重作东南尉，生涯尚似僧。","客程淮馆月，乡思海船灯。","晚雾看春毂，晴天见朗陵。","不应三考足，先授诏书征。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-5839dca5-f3dc-4626-9eac-5d2baca3f55c","tags":[]},{"id":"poem-31324d6b53b6d8dd735fd006","title":"山中期张芬不至","author":"李端","dynasty":"唐","verses":["石堤春草碧，双燕向西飞。","怅望云天暮，佳人何处归。","药栏虫网遍，苔井水痕稀。","谁道嵇康嬾，山中自掩扉。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-9991691b-23a6-463b-9eef-0f36027d8a9b","tags":[]},{"id":"poem-313cdb48ca2c121d2f008c53","title":"句","author":"伍乔","dynasty":"宋","verses":["积霭沈诸壑，微阳在半峰。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-b040252b-980a-4375-b940-dfdc58198c48","tags":[]},{"id":"poem-3145fcaa784dd3e4c6dd4559","title":"塞上","author":"高适","dynasty":"唐","verses":["东出卢龙塞，浩然客思孤。","亭堠列万里，汉兵犹备胡。","边尘涨北溟，虏骑正南驱。","转鬬岂长策，和亲非远图。","惟昔李将军，按节出皇都。","总戎扫大漠，一战擒单于。","常怀感激心，愿效纵横谟。","倚劒欲谁语，关河空郁纡。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-0111fccd-210b-4e0d-b8f7-c4b09ed8476f","tags":[]},{"id":"poem-314d6d2c3e252739760d5872","title":"卜算子·缺月挂疏桐","author":"苏轼","dynasty":"宋","verses":["缺月挂疏桐，漏断人初静。","时见幽人独往来，缥缈孤鸿影。","惊起却回头，有恨无人省。","拣尽寒枝不肯栖，枫落吴江冷。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-41","tags":["宋词三百首"]},{"id":"poem-3154f80a5b480ce771c26c52","title":"兵要望江南 禳厌第二十四（京本作「占厌禳第十九」○十三首） 九","author":"易静","dynasty":"唐","verses":["北方阵，羽姓显然明。","骓马乌衣如北斗，黑旗玄武队前行，贼将势摧倾。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-28fb8b32-3882-4969-bd3f-d113d1448de4","tags":[]},{"id":"poem-3156e6f20d0f02df7047600a","title":"村醉","author":"卢仝","dynasty":"唐","verses":["昨夜村饮归，健倒三四五。","摩挲青莓苔，莫嗔惊著汝。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-0a2ac536-d749-4430-b92c-aa82369da683","tags":[]},{"id":"poem-31594d6c748ee22dab609bf3","title":"诉衷情令·阿房废址汉荒丘","author":"康与之","dynasty":"宋","verses":["阿房废址汉荒丘。","狐兔又群游。","豪华尽成春梦，留下古今愁。","君莫上，古原头。","泪难收。","夕阳西下，塞雁南飞，渭水东流。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-300","tags":[]},{"id":"poem-315a379ec625613c6d451a51","title":"蝶恋花·面旋落花风荡漾","author":"欧阳修","dynasty":"宋","verses":["面旋落花风荡漾。","柳重烟深，雪絮飞来往。","雨后轻寒犹未放。","春愁酒病成惆怅。","枕畔屏山围碧浪。","翠被华灯，夜夜空相向。","寂寞起来褰绣幌。","月明正在梨花上。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-633","tags":[]},{"id":"poem-31619c9d8eaba86f50dcfd2d","title":"菩萨蛮 其十","author":"温庭筠","dynasty":"唐","verses":["宝函钿雀金㶉𫛶，沉香阁上吴山碧。","杨柳又如丝，驿桥春雨时。","画楼音信断，芳草江南岸。","鸾镜与花枝，此情谁得知。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-1-juan.json#record-9","tags":[]},{"id":"poem-31731b5335e2decc33a27fb2","title":"佚老堂为丞相文安公作  其一","author":"綦崇礼","dynasty":"宋","verses":["社稷功名不自贤，小园卜筑赏闲年。","脱遗富贵还身外，收拾芳菲寓目前。","未息烟尘劳瞩望，莫孤风月且留连。","一时赋咏多奇作，江汉崧髙好共编。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-8061574b-9585-4272-b0c5-a72332b1dd0b","tags":[]},{"id":"poem-3173ec1c0a20ee0eeff311c2","title":"春酿","author":"赵嘏","dynasty":"唐","verses":["春酿正风流，梨花莫问愁。","马卿思一醉，不惜鹔鹴裘。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-fcd93539-7f6d-4bda-ae35-3db7176cf8b5","tags":[]},{"id":"poem-3179db54cb3decfa8c804e3a","title":"洞仙歌·轻痕浅晕","author":"高观国","dynasty":"宋","verses":["轻痕浅晕。","偷染春风面。","恰似西施影儿现。","拟新妆、临槛一段天真，闲态度，长恁香娇玉软。","从今怀袖里，不暂相离，似笑如颦任舒卷。","顾芳容不老，只似如今，娇不语、无奈情深意远。","便雨隔云疏暂分携，也时展丹青，见伊一见。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-402","tags":[]},{"id":"poem-317eccba087907c56d7f8ab0","title":"村墅","author":"崔道融","dynasty":"唐","verses":["正月二月村墅闲，余粮未乏人心宽。","南邻雨中揭屋笑，酒熟数家来相看。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-b19282c0-6f4c-4824-a886-31587743db98","tags":[]},{"id":"poem-317eea887e1852ab23db02bc","title":"渔歌子·荻花秋","author":"李珣","dynasty":"五代","verses":["荻花秋，潇湘夜，橘洲佳景如屏画。","碧烟中，明月下，小艇垂纶初罢。","水为乡，篷作舍，鱼羹稻饭常餐也。","酒盈杯，书满架，名利不将心挂。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-x-juan.json#record-18","tags":[]},{"id":"poem-318659b13271e56a185ab1dc","title":"秣陵怀古","author":"纳兰性德","dynasty":"清","verses":["山色江声共寂寥，十三陵树晚萧萧。","中原事业如江左，芳草何须怨六朝。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-141","tags":[]},{"id":"poem-31878234bef4b1ae8cc1f15c","title":"四五","author":"王梵志","dynasty":"唐","verses":["逢人须歛手，避道莫前荡。","（一本作「汤」。","）忽若相冲着，（「忽若」，斯三三九三卷作「忽然」。","）他{弓|一/虫}（郑本作强。","）必自伤。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-4d4125a6-37aa-4f87-92f5-cfa925fbc5e8","tags":[]},{"id":"poem-318d612391dfc3cfbab3a3ce","title":"送韩司直","author":"皇甫冉","dynasty":"唐","verses":["（见宋赵师秀《众妙集》，并见宋周弼《唐三体诗》卷六。","按《全唐诗》卷一百八十四作刘长卿诗，诗同，校其异文如下：首句「游吴还适越」，「适」，《全唐诗》作「入」。","五句「山明残雪在」，「山」，《全唐诗》作「岸」。","七句「季子留遗庙」，《全唐诗》作「季子杨柳庙」。","又《唐三体诗》本元释圆至于此句下注曰：「皇览《冢墓记》：季子冢在毘陵县暨阳乡，至今吏唐民祀事。","」〖唐姚合《极玄集》、宋计有功《唐诗纪事》卷二七均作皇甫冉诗，《文苑英华》卷二七二作皇甫曾诗，《四部丛刊》影明正德本《刘随州文集》卷三则作刘诗。","似亦皇甫冉所作为是。","〗）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-6ed1abf1-bde8-49be-aa66-0c36c8583c93","tags":[]},{"id":"poem-3190da259e7cf80006e96132","title":"送曾秀才","author":"徐铉","dynasty":"宋","verses":["淦水神仙宅，仙山夹县楼。","吾孙好诗句，归咏故乡秋。","紫竹遮书幌，红蕉拂钓舟。","东堂有平路，莫谒外诸侯。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-6336e7f1-7244-49e2-8aec-a559e871c039","tags":[]},{"id":"poem-319880bdf10cc7866707584c","title":"太子刘舍人邀看花","author":"陆畅","dynasty":"唐","verses":["年少风流七品官，朱衣白马冶游盘。","负心不报春光主，几处偷看红牡丹。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-a0255d23-1e3b-4c2d-a6bf-7deb4477ade6","tags":[]},{"id":"poem-319f4563657f14c9f839fe0a","title":"桐江闲居作十二首 十二","author":"贯休","dynasty":"唐","verses":["囊非扑满器，门更绝人过。","土井连冈冷，风帘迸叶多。","村童顽似铁，山菜硬如莎。","唯有前山色，窗中无奈何。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-cf25b759-79db-45d1-9b69-610f5d730ff4","tags":[]},{"id":"poem-31c2c2cd352b1e3add8e1ee5","title":"·","author":"杨夔","dynasty":"唐","verses":["。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-56b117e3-2c41-4566-9c29-102b42b1dafd","tags":[]},{"id":"poem-31c6f53fdef9442958be333b","title":"席上酬东川严中丞叙旧见赠","author":"薛逢","dynasty":"唐","verses":["昔记披云日，今逾二十年。","声名俱是梦，恩旧半归泉。","朱绂慙衰齿，红妆惨别筵。","离歌正凄切，休更促危弦。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-d297092f-106d-4103-b3b2-32ffaca6ea56","tags":[]},{"id":"poem-31cd35b1c8b0aeec2e9fb2c4","title":"和元晦晚霞","author":"张栻","dynasty":"宋","verses":["早来雪意遮空碧，晚喜晴霞散绮红。","便可悬知明旦事，一轮明月快哉风。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-5b4013df-f5a2-4045-bb09-6e41bd51b2ae","tags":[]},{"id":"poem-31d4136111fe6950626a47fc","title":"次韵程公辟暮春","author":"苏颂","dynasty":"宋","verses":["日日寻春春欲还，园林游兴未应阑。","间关鶑啭冲牙韵，烂漫花开历绿团。","须信马蹄随处健，肯教金盏暂时干。","休惊节物频更换，适意欢娱定一般。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-a0012adf-f67e-4ddd-815c-1631e98dc36f","tags":[]},{"id":"poem-31d8bda95d6e6b26aef11619","title":"偈颂（幷序○序为南岳齐己撰） 九","author":"居遁","dynasty":"唐","verses":["自体如如任运常，因兹行歇在三湘。","双眉无用是毫相，说处无分舌广长。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-bc038b95-b2f4-4b35-8840-2c1f897a9be7","tags":["衡山"]},{"id":"poem-31fc6a21a9657d1d25f9fc94","title":"剔银灯·江上秋高霜早","author":"沈邈","dynasty":"宋","verses":["江上秋高霜早。","云静月华如扫。","候雁初飞，啼螀正苦，又是黄花衰草。","等闲临照。","潘郎鬓、星星易老。","那堪更、酒醒孤棹。","望千里、长安西笑。","臂上妆痕，胸前泪粉，暗惹离愁多少。","此情谁表。","除非是、重相见了。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-47","tags":[]},{"id":"poem-31fe60d987709544e423f3a7","title":"塞北二首 二","author":"沈佺期","dynasty":"唐","verses":["胡骑犯边埃，风从丑上来。","五原烽火急，六郡羽书催。","冰壮飞狐[冷]，霜浓候雁哀。","将军朝授钺，战士夜衔枚。","紫塞金河里，葱山铁勒隈。","莲花秋劒发，桂叶晓旗开。","秘略三军动，妖氛百战摧。","何言投笔去，终作勒铭回。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-a611c4f0-e97c-4cb1-ab4c-fcd5b4a8a19d","tags":[]},{"id":"poem-3202da3bb36300ea30f49b1c","title":"风流子·少年多行乐","author":"谢懋","dynasty":"宋","verses":["少年多行乐，方豪健、何处不嬉游。","记情逐艳波，暖香斜径，醉摇鞭影，扑絮青楼。","难忘是，笑歌偏婉娩，乡号得温柔。","娇雨娱云，旋宽衣带，剩风残月，都在眉头。","一成憔悴损，人惊怪，空自引镜堪羞。","谁念短封难托，征雁虚浮。","念夜寒灯火，懒寻前梦，满窗风雨，供断闲愁。","情到不堪言处，却悔风流。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-298","tags":[]},{"id":"poem-32033d60484d121c9a930eab","title":"南乡子·为亡妇题照","author":"纳兰性德","dynasty":"清","verses":["泪咽却无声。","只向从前悔薄情，凭仗丹青重省识。","盈盈。","一片伤心画不成。","别语忒分明。","午夜鹣鹣梦早醒。","卿自早醒侬自梦，更更。","泣尽风檐夜雨铃。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-153","tags":[]},{"id":"poem-32046cb983ba5cf23ffb89a9","title":"醉公子·慢绾青丝发","author":"薛昭蕴","dynasty":"五代","verses":["慢绾青丝发，光砑吴绫袜。","床上小熏笼，韶州新退红。","叵耐无端处，捻得从头污。","恼得眼慵开，问人闲事来。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-3-juan.json#record-41","tags":[]},{"id":"poem-3211fb2528334df4f53adc83","title":"奉和柳相公中书言怀","author":"包佶","dynasty":"唐","verses":["运筹时所贵，前席礼偏深。","羸驾归贫宅，攲冠出禁林。","凤巢方得地，牛喘最关心。","雅望期三入，东山未可寻。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-23ecc4c8-9ab8-4d67-a68c-1d2f0e57f0ff","tags":[]},{"id":"poem-32138cc731fb6397d5b17dfe","title":"范真传侍御累有寄因奉酬十首 六","author":"鲍溶","dynasty":"唐","verses":["红袂歌声起，因君始得闻。","黄昏小垂手，与我驻浮云。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-5c0c4358-ade3-427e-80b9-e5e3dc0494a6","tags":[]},{"id":"poem-321b7016b49ce75039764889","title":"长安感怀","author":"张祜","dynasty":"唐","verses":["家寄东吴西入秦，三年虚度帝城春。","流光渐渐到华髪，离恨萧萧生白苹。","楚梦觉来愁翠被，越吟声尽怨芳尘。","更闻玉笛吹明月，一曲风前泪满巾。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-6c83e8a1-2ad0-4df4-8dd0-59ddea35f906","tags":[]},{"id":"poem-32205bf63b287f62030c3014","title":"送友人","author":"李白","dynasty":"唐","verses":["青山横北郭，白水绕东城。","此地一为别，孤篷万里征。","浮云游子意，落日故人情。","挥手自兹去，萧萧斑马鸣。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-送友人","tags":[]},{"id":"poem-3224e68d1dbc3453aeb90610","title":"咏史诗 细柳营","author":"胡曾","dynasty":"唐","verses":["文帝銮舆劳北征，条侯此地整严兵。","辕门不峻将军令，今日争知细柳营。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-251e270e-c9ab-4d52-bb85-560570f12a70","tags":[]},{"id":"poem-322bfd194303fab173cdb3e4","title":"墨藕花  其二","author":"释居简","dynasty":"宋","verses":["西子湖阴锦掞云，水风池阁度晴熏。","影窥明王生绡薄，分外精神一两分。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-eda815b1-77ac-440c-8f3c-9dbd7b578558","tags":["西湖"]},{"id":"poem-323142ccdea521f314b77c52","title":"海棠","author":"苏轼","dynasty":"宋","verses":["东风袅袅泛崇光，香雾空蒙月转廊。","只恐夜深花睡去，故烧高烛照红妆。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-海棠","tags":[]},{"id":"poem-3232089fa58e7a31abd1e01f","title":"朝日勅赐百官樱桃","author":"张籍","dynasty":"唐","verses":["仙果人间都未有，今朝忽见下天门。","捧盘小吏初宣勅，当殿群臣共拜恩。","日色遥分门下坐，露香才出禁中园。","每年重此先偏待，愿得千春奉至尊。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-7ef7bc94-3b3f-4224-ba4c-889a39870e38","tags":[]},{"id":"poem-32364b4af359f610cf228ddc","title":"故燕国相公挽歌二首 二","author":"李嘉祐","dynasty":"唐","verses":["共美持衡日，皆言折槛时。","蜀侯供庙略，汉主缺台司。","车马行仍止，笳箫咽又悲。","今年杜陵陌，殄瘁百花迟。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-5a5dcd73-11dd-46df-9eb3-e345148ad909","tags":[]},{"id":"poem-323b47dc177434653798ce18","title":"赠心上人","author":"释居简","dynasty":"宋","verses":["一抹新霜雁背寒，满庭疎雨客衣单。","苦心莫负韦编绝，岁晚归来语夜阑。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-145360f2-dd28-41e7-b1fa-e87851b6160f","tags":[]},{"id":"poem-323b8c0c98aadfbf95378057","title":"前腔","author":"刘唐卿《白兔记》","dynasty":"元","verses":["(末)听吾言道，不须烦恼。","你若缺少盘缠，顷刻令人送到。","他若昧心，他若昧心，上有苍天知道，必然还报。","自今朝，步辇登程去，坚心莫惮劳。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8880","tags":[]},{"id":"poem-324f00260862350066bb7b2d","title":"吉日","author":"佚名","dynasty":"先秦","verses":["吉日维戊，既伯既祷。田车既好，四牡孔阜。升彼大阜，从其群丑。","吉日庚午，既差我马。兽之所同，麀鹿麌麌。漆沮之从，天子之所。","瞻彼中原，其祁孔有。儦儦俟俟，或群或友。悉率左右，以燕天子。","既张我弓，既挟我矢。发彼小豝，殪此大兕。以御宾客，且以酌醴。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-179","tags":[]},{"id":"poem-326bad15d3f73760404e5821","title":"过卢秦卿旧居","author":"司空曙","dynasty":"唐","verses":["五柳茅茨楚国贤，桔槔蔬圃水涓涓。","黄花寒后难逢蝶，红叶晴来忽有蝉。","韩康助采君臣药，支遁同看内外篇。","为问潜夫空著论，如何侍从赋甘泉。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-f3dcc157-7b7f-43a1-b884-2aec0694612e","tags":[]},{"id":"poem-326f849101c3231efb8864e3","title":"和陶渊明归田园居六诗  其一","author":"陈造","dynasty":"宋","verses":["一室类蜂房，为食来穷山。","仅救饥火煎，跋履恐雕年。","平生丘壑念，回首鱼脱渊。","乡居何许家，菰茭满中田。","有儿可耕牧，枉滞章句间。","昨日鹊啅余，鴈书忽堕前。","云集南荡工，数灶腾青烟。","书卖犹可市，前功戒颓颠。","官业讵宜老，倦客志在闲。","置书命鸱夷，心事今泰然。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-22ac3c1a-6bb3-4956-a101-726daf34a4e0","tags":[]},{"id":"poem-32710bf42ce5fc2150922fce","title":"挽林通判德溥  其一","author":"林光朝","dynasty":"宋","verses":["岂为长者畏时名，梁楚何从得此声。","只隔螺江衣带水，自应别驾旧廉平。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-9c60614f-120b-47ea-83e3-b2a1264babea","tags":[]},{"id":"poem-32773c1509a7eeb8f2e08473","title":"女冠子·星冠霞帔","author":"牛峤","dynasty":"五代","verses":["星冠霞帔，住在蕊珠宫里。佩玎珰。","明翠摇蝉翼，纤珪理宿妆。","醮坛春草绿，药院杏花香。","青鸟传心事，寄刘郎。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-4-juan.json#record-2","tags":[]},{"id":"poem-32799e7a672d79f6a85db6c2","title":"秋日独游曲江","author":"杨凭","dynasty":"唐","verses":["信马闲过忆所亲，秋山行尽路无尘。","主人莫惜松阴醉，还有千钱沽酒人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-f00e57ab-0566-404a-aef0-1762ef4933f7","tags":[]},{"id":"poem-32889382477243fd1769a767","title":"诉衷情·烧残绛蜡泪成痕","author":"杜安世","dynasty":"宋","verses":["烧残绛蜡泪成痕。","街鼓报黄昏。","碧云又阻来信，廊上月侵门。","愁永夜，拂香裀。","待谁温。","梦兰憔悴，掷果凄凉，两处消魂。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-950","tags":[]},{"id":"poem-3292611dd38014eb6a0df321","title":"桂枝香","author":"刘唐卿《白兔记》","dynasty":"元","verses":["孩儿一去，眼中流泪，全无力气精神。","更兼纷纷细雨，酸疼两腿两腿难移，前去如何存济？闷心儿一两阵西风起，滴溜溜败叶飞。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8962","tags":[]},{"id":"poem-3294a5700ef9bc07330f30b1","title":"赠城郭道士","author":"孟郊","dynasty":"唐","verses":["望里失却山，听中遗却泉。","松枝休策云，药囊翻贮钱。","曾依青桂隣，学得白雪弦。","别来意未回，世上为隐仙。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-a4a41811-d96e-4c66-bd18-54f4a135d638","tags":[]},{"id":"poem-32956b1be5f3a9936a21a38e","title":"访友人不遇","author":"李咸用","dynasty":"唐","verses":["出门无至友，动即到君家。","空掩一庭竹，去看何寺花。","短童应捧杖，稚女学擎茶。","吟罢留题处，苔阶日影斜。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-51c51f72-e949-436f-a59b-7f8d0ddb8b8b","tags":[]},{"id":"poem-32ababce88ee8e8fe65414ff","title":"春怨","author":"金昌绪","dynasty":"唐","verses":["打起黄莺儿，莫教枝上啼。","啼时惊妾梦，不得到辽西。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-b41e25f5-5a57-497f-a3a2-84bdfb9331f5","tags":["唐诗三百首","怀人","五言绝句","闺怨"]},{"id":"poem-32b3c91dd608d347f26b788b","title":"河传·秋雨","author":"阎选","dynasty":"五代","verses":["秋雨，秋雨，无昼无夜，滴滴霏霏。","暗灯凉簟怨分离，妖姬，不胜悲。","西风稍急喧窗竹，停又续，腻脸悬双玉。","几回邀约雁来时，违期，雁归，人不归。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-9-juan.json#record-26","tags":[]},{"id":"poem-32b984f54214c528cf7dbb8e","title":"采薇","author":"佚名","dynasty":"先秦","verses":["采薇采薇，薇亦作止。曰归曰归，岁亦莫止。靡室靡家，𤞤狁之故。不遑启居，𤞤狁之故。","采薇采薇，薇亦柔止。曰归曰归，心亦忧止。忧心烈烈，载饥载渴。我戍未定，靡使归聘。","采薇采薇，薇亦刚止。曰归曰归，岁亦阳止。王事靡盬，不遑启处。忧心孔疚，我行不来！","彼尔维何？维常之华。彼路斯何？君子之车。戎车既驾，四牡业业。岂敢定居？一月三捷。","驾彼四牡，四牡骙骙。君子所依，小人所腓。四牡翼翼，象弭鱼服。岂不日戒？𤞤狁孔棘！","昔我往矣，杨柳依依。今我来思，雨雪霏霏。行道迟迟，载渴载饥。我心伤悲，莫知我哀！"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-166","tags":[]},{"id":"poem-32be58c4f99412c952a5d86b","title":"人南渡・感皇恩·兰芷满芳洲","author":"贺铸","dynasty":"宋","verses":["兰芷满芳洲，游思横路。","罗袜尘生步。","迎顾。","整鬟颦黛，脉脉两情难语。","细风吹柳絮。","人南渡。","回首旧游，山无重数。","花底深朱户。","何处。","半黄梅子，向晚一帘疏雨。","断魂分付与。","春将去。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-74","tags":["宋词三百首"]},{"id":"poem-32c596c7390935d672c3662b","title":"郊庙歌辞 汉宗庙乐舞辞 灵长舞","author":"张昭","dynasty":"唐","verses":["天降祥，汉祚昌。","火炎上，水灵长。","建庙社，洁蒸尝。","罗钟石，俨珩璜。","陈玉豆，酌金觞。","气昭感，德馨香。","祗洛汭，瞻晋阳。","降吾祖，福穰穰。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-07232e95-0109-4302-ad90-957ca3c2cd2f","tags":[]},{"id":"poem-32c77dd366938107abf87b69","title":"叔于田","author":"佚名","dynasty":"先秦","verses":["叔于田，巷无居人。岂无居人？不如叔也。洵美且仁。","叔于狩，巷无饮酒。岂无饮酒？不如叔也。洵美且好。","叔适野，巷无服马。岂无服马？不如叔也。洵美且武。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-76","tags":[]},{"id":"poem-32d853ea302e9bca2ca67887","title":"西地锦","author":"徐田臣《杀狗记》","dynasty":"元","verses":["幸得一人有庆，万民咸赖康宁。","蛮夷拱手米皈顺，奉国泰民清。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-1942","tags":[]},{"id":"poem-32f17286f05c2dd6b983c696","title":"诉衷情·莺语花舞春昼午","author":"温庭筠","dynasty":"唐","verses":["莺语花舞春昼午，雨霏微。","金带枕，宫锦，凤凰帷。","柳弱蝶交飞，依依。","辽阳音信稀，梦中归。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-2-juan.json#record-4","tags":[]},{"id":"poem-32f25fc656704ac34b508753","title":"贺新郎·湛湛长空黑","author":"刘克庄","dynasty":"宋","verses":["湛湛长空黑。","更那堪、斜风细雨，乱愁如织。","老眼平生空四海，赖有高楼百尺。","看浩荡、千崖秋色。","白发书生神州泪，尽凄凉、不向牛山滴。","追往事，去无迹。","少年自负凌云笔。","到而今、春华落尽，满怀萧瑟。","常恨世人新意少，爱说南朝狂客。","把破帽、年年拈出。","若对黄花孤负酒，怕黄花、也笑人岑寂。","鸿北去，日西匿。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-55","tags":["宋词三百首"]},{"id":"poem-32f8a1d340055424338462b5","title":"有女同车","author":"佚名","dynasty":"先秦","verses":["有女同车，颜如舜华。将翱将翔，佩玉琼琚。彼美孟姜，洵美且都。","有女同行，颜如舜英。将翱将翔，佩玉将将。彼美孟姜，德音不忘。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-82","tags":[]},{"id":"poem-32fde0dd6a79d7185964caaf","title":"感皇恩·画舸白苹洲","author":"程大昌","dynasty":"宋","verses":["画舸白苹洲，如归故里。","老幼欢迎僮婢喜。","较量心事，岁岁春风弧矢。","今年称寿处，尤欢美。","嫁得黔娄，苦耽书史。","文字流传曾贵纸。","便同黼黻，何似实头龟紫。","天公闻此语，应怜许。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-248","tags":[]},{"id":"poem-3304089b1eba2973d7213920","title":"六七","author":"王梵志","dynasty":"唐","verses":["知恩须报恩，有恩莫不更。","（「更」，伯三五五八、伯三七一六、伯三六五六卷作「报」。","）[更]在枯井中，（「更」字据伯三五五八卷补。","）谁能重来救。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-382812d7-8b9e-4636-8cff-bd020bee427f","tags":[]},{"id":"poem-3305cdd96fc8e0aa8c777e6a","title":"马明生遇王婉罗","author":"李翔","dynasty":"唐","verses":["彻骨金疮分已休，谢神妃护到灵丘。","供丞（承）洞府知何地，洒扫云房不记秋。","金锁玉函虽照燿，宝书真篆敢规（窥）求。","龙胎未肯传初学，又逐安期万里游。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-3f8002ae-3229-4887-8438-03ae13fadddf","tags":[]},{"id":"poem-33085206c80fca4831351e83","title":"定风波·对酒追欢莫负春","author":"欧阳修","dynasty":"宋","verses":["对酒追欢莫负春。","春光归去可饶人。","昨日红芳今绿树。","已暮。","残花飞絮两纷纷。","粉面丽姝歌窈窕。","清妙。","尊前信任醉醺醺。","不是狂心贪燕乐。","自觉。","年来白发满头新。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-736","tags":[]},{"id":"poem-330a05879cc9926b692eb0e2","title":"善哉行 其一","author":"曹操","dynasty":"汉","verses":["古公亶甫，积德垂仁。","思弘一道，哲王于豳。","太伯仲雍，王德之仁。","行施百世，断发文身。","伯夷叔齐，古之遗贤。","让国不用，饿殂首山。","智哉山甫，相彼宣王。","何用杜伯，累我圣贤。","齐桓之霸，赖得仲父。","后任竖刁，虫流出户。","晏子平仲，积德兼仁。","与世沈德，未必思命。","仲尼之世，主国为君。","随制饮酒，扬波使官。"],"enabled":true,"collection":"曹操诗集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/曹操诗集/caocao.json#record-18","tags":[]},{"id":"poem-330e3a74b8375f0072b23908","title":"归嵩山作","author":"王维","dynasty":"唐","verses":["清川带长薄，车马去闲闲。","流水如有意，暮禽相与还。","荒城临古渡，落日满秋山。","迢递嵩高下，归来且闭关。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-40cd6eec-c6ce-4659-a225-61063cd210e9","tags":["唐诗三百首","山水","写景","抒情","五言律诗"]},{"id":"poem-3323786b26c95fab1abc97dd","title":"浣溪沙·春色迷人恨正赊","author":"顾敻","dynasty":"五代","verses":["春色迷人恨正赊，可堪荡子不还家，细风轻露着梨花。","帘外有情双燕飏，槛前无力绿杨斜，小屏狂梦极天涯。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-7-juan.json#record-0","tags":[]},{"id":"poem-332e995678580b1d523ea376","title":"四明陆韩二佳友登科  其一","author":"释居简","dynasty":"宋","verses":["龙虎榜头千佛名，乱山寸碧起双明。","预吟新句虽三首，莫放胪传第二声。","得意马蹄须款曲，吐花兔颖看峥嵘。","平生两眼人嫌白，青为君家好弟兄。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-402165a8-12f0-4e9b-b479-afac6d216378","tags":[]},{"id":"poem-333014ab58cfe95ad8c2ddf8","title":"兵要望江南 占六壬第二十八（京本列第十七○四十五首） 十二","author":"易静","dynasty":"唐","verses":["经险路，惟是（京本作「则」、辛本、川本作「为则」）忌天罡。","加孟前行喜（辛本、川本、京本作「应」）不喜，罡临四仲己中伤，加季后（京本作「复」）逃亡。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-d8632507-aa54-4001-82c4-3b019dca004e","tags":[]},{"id":"poem-333df364d2556654dd9da056","title":"题钟隐画鹖子鸟","author":"金昌宗","dynasty":"唐","verses":["多厌翻翔下苇丛，戢翰侧脑思何穷？","侍童莫便褰帘过，只恐惊飞入碧空。","（见宋刘道醇《五代名画补遗》。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-fad9da7f-53db-4866-8ff0-38fa42f6255c","tags":[]},{"id":"poem-334553124a38e0bdef1024f8","title":"临江仙·莺报帘前暖日红","author":"李珣","dynasty":"五代","verses":["莺报帘前暖日红，玉炉残麝犹浓。","起来闺思尚疏慵，别愁春梦，谁解此情悰。","强整娇姿临宝镜，小池一朵芙蓉。","旧欢无处再寻踪，更堪回顾，屏画九疑峰。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-x-juan.json#record-24","tags":[]},{"id":"poem-33468a73c0ff2b0205b235d8","title":"送卢孟明还上都","author":"皎然","dynasty":"唐","verses":["江臯北风至，归客独伤魂。","楚水逢乡雁，平陵忆故园。","征骖嘶别馆，落日隐寒原。","应及秦川望，春华满国门。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-743b9ff6-ef74-4619-a1fb-8b677a3baa9d","tags":[]},{"id":"poem-334a22eec73fc17d631159cb","title":"嵩山十志十首 其五","author":"卢鸿一","dynasty":"唐","verses":["水攒冲兮石丛耸，焕云锦兮喷汹涌。","苔駮荦兮草夤缘，芳幂幂兮濑溅溅。","石攒丛兮云锦淙，波连珠兮文沓綘。","有洁冥者媚此幽，漱灵液兮乐天休，实获我心兮夫何求。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-64d377ec-aa69-468e-8c30-2ccc80b3fbd2","tags":[]},{"id":"poem-335072e0f7daa14bd2b96057","title":"春日杂兴十五首  其一二","author":"华镇","dynasty":"宋","verses":["江梅灿瑶琨，绪风未成和。","红药簇云锦，韶光已蹉跎。","腊寒苦难任，秋阳暴如何。","宁知桃李树，乘春蔚婆娑。","二月艳阳天，两京佳丽多。","五陵浮瑞气，三州翻绿波。","宫槐出华阙，御柳夹银河。","玄鸟杂飞舞，黄鹂竞鸣歌。","芳蹊展平练，繁艳簇香罗。","浥露笑金谷，迎风媚铜驼。","落英纵纷纷，珍实已峨峨。","莫讶潘河阳，盈城意靡他。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-04203c49-94f1-445d-ab22-83a4f97be976","tags":[]},{"id":"poem-33539f4e665ae39bf0af2f1c","title":"送李补阙摄御史充河西节度判官","author":"孙逖","dynasty":"唐","verses":["昔年叨补衮，边地亦埋轮。","官序慙先达，才名畏后人。","西戎虽献款，上策耻和亲。","早赴前军幕，长清外域尘。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-ee037111-955b-4523-9280-294c7a2c39ac","tags":[]},{"id":"poem-33555df997cc85c6938fa03a","title":"奉和武功学士舍人纪赠文懿大师浄公  其五","author":"徐铉","dynasty":"宋","verses":["只有闲情搜景物，不将客鬓惜流光。","京华才子多文会，众许清词每擅场。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-b93df849-b16c-4952-a85c-e0223c21a03e","tags":[]},{"id":"poem-3355fc9d6fa74db6097f6211","title":"崇礼次韵奉酬聊致挽留之意","author":"綦崇礼","dynasty":"宋","verses":["归艎少缓不须摧，更待东城一访梅。","铁石心情犹解赋，芝兰风味合相陪。","腊残绝讶迟迟见，春近何妨得得来。","清赏未谐君欲去，临邛谁与共衔杯。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-2e25e203-c99d-41c8-b410-233f733b7923","tags":[]},{"id":"poem-335763d1823223ba006957a1","title":"赤枣子·惊晓漏","author":"纳兰性德","dynasty":"清","verses":["惊晓漏，护春眠。","格外娇慵只自怜。","寄语酿花风日好，绿窗来与上琴弦。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-22","tags":[]},{"id":"poem-335f4c42071206f376902682","title":"南至日太史登台书云物","author":"裴逵","dynasty":"唐","verses":["圆丘才展礼，佳气近初分。","太史新簪笔，高台纪彩云。","烟空和缥缈，晓色共氛氲。","道泰资贤辅，年丰荷圣君。","恭惟司国瑞，兼用察人文。","应念怀铅客，终朝望碧雰。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-01199cd7-9a2a-4489-8b81-2a61043b2d01","tags":[]},{"id":"poem-336e8dc2d415777a54291fcc","title":"过王濬墓（二首）","author":"李休烈","dynasty":"唐","verses":["。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-9b7fca10-a376-4e86-97d1-11e69bf55f2e","tags":[]},{"id":"poem-336f8f3b421316e257f2f7db","title":"寄宜阳兄弟","author":"易重","dynasty":"唐","verses":["六年雁序恨分离，诏下今朝遇已知。","上国皇风初喜日，御堦恩渥属身时。","内庭再考称文异，圣主宣名奖艺奇。","故里仙才若相问，一春攀得两重枝。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-4f11dd0a-0bac-48a1-89a4-dcf9902c2fa0","tags":[]},{"id":"poem-3376cb91c11b39af8828024b","title":"清明日与友人游玉粒塘庄","author":"来鹄","dynasty":"唐","verses":["几宿春山逐陆郎，清明时节好烟光。","归穿细荇船头滑，醉踏残花屐齿香。","风急岭云飘迥野，雨余田水落方塘。","不堪吟罢东回首，满耳蛙声正夕阳。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-b70cb525-c13d-410e-b14d-d625f88d3eab","tags":[]},{"id":"poem-3385639e6f4ed6b552cddbe2","title":"蝉","author":"张乔","dynasty":"唐","verses":["先秋蝉一悲，长是客行时。","曾感去年者，又鸣何处枝。","细听残韵在，回望旧声迟。","断续谁家树，凉风送别离。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-8a678775-f915-49b4-90ec-10684835be2a","tags":[]},{"id":"poem-338d88669572370325c72d8a","title":"水调歌头·凤舞龙蟠处","author":"关注","dynasty":"宋","verses":["凤舞龙蟠处，玉室与金堂。","平生想望真境，依约在何方。","谁信许君丹灶，便与吴君遗剑，只在洞天傍。","若要安心地，便是远名场。","几年来，开林麓，建山房。","安眠饱馆清坐，无事可思量。","洗尽人间忧患，看尽仙家风月，和气满清扬。","一笑尘埃外，云水远相忘。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-243","tags":[]},{"id":"poem-339315e76572fbadeed31db5","title":"听晓角","author":"李益","dynasty":"唐","verses":["边霜昨夜堕关榆，吹角当城汉月孤。","无限塞鸿飞不度，秋风卷入小单于。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-426eea46-266e-472d-8fe4-a558b28d18f9","tags":["写景","凄凉","萧瑟","秋天","边塞"]},{"id":"poem-33973e91d10669336431686d","title":"北行留别","author":"杨凌","dynasty":"唐","verses":["日日山川烽火频，山河重起旧烟尘。","一生孤负龙泉劒，羞把诗书问故人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-5770b5d6-3ea9-443a-8159-14d2b05771f6","tags":[]},{"id":"poem-33a23a5df662491b62f9d946","title":"杂曲歌辞 清平调 三","author":"李白","dynasty":"唐","verses":["名花倾国两相欢，长得君王带笑看。","解释春风无限恨，沈香亭北倚阑干。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-0db5450e-f1e0-4d53-8106-529def535537","tags":["唐诗三百首","乐府","写人","花","写花","近代曲辞"]},{"id":"poem-33a99470cbd10891920004ab","title":"社日","author":"张演","dynasty":"唐","verses":["鹅湖山下稻粱肥，豚栅鸡栖对掩扉。","桑柘影斜春社散，家家扶得醉人归。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-社日","tags":[]},{"id":"poem-33aba7cf4229abb15d437b31","title":"望毛女峰","author":"陆畅","dynasty":"唐","verses":["我种东峰千叶莲，此峰毛女始求仙。","今朝暗算当时事，已是人间七万年。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-502400a5-4514-4981-a304-cf170774fc25","tags":[]},{"id":"poem-33af2881e39e35690f4c00c8","title":"题女道士居","author":"马戴","dynasty":"唐","verses":["不饵住云溪，休丹罢药畦。","杏花虚结子，石髓任成泥。","扫地青牛卧，栽松白鹤栖。","共知仙女丽，莫是阮郎妻。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-ebcd3d59-79c6-4ad3-8dad-4d26c961bd2a","tags":[]},{"id":"poem-33b1a7b95db671b70f532fa2","title":"踏莎行·浓润侵衣","author":"仲殊","dynasty":"宋","verses":["浓润侵衣，暗香飘砌。","雨中花色添憔悴。","凤鞋湿透立多时，不言不语厌厌地。","眉上新愁，手中文字。","因何不倩鳞鸿寄。","想伊只诉薄情人，官中谁管闲公事。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-885","tags":[]},{"id":"poem-33c1b97c4c92075a29ec48f4","title":"苏州有感","author":"宋伯仁","dynasty":"宋","verses":["秋意满姑苏，扁舟忆五湖。","铃声边报急，帆影客心孤。","野港青如染，遥山澹欲无。","英雄应念我，时事满银须。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-cdf79a17-9100-41d8-9d84-ef38cb52d9b8","tags":[]},{"id":"poem-33d5af05c435c26d9c33b72f","title":"四边静","author":"徐田臣《杀狗记》","dynasty":"元","verses":["(生)思之两个忘恩的，教人恨切齿。","错认定盘星，教缘我不是。","(合)把从前是非，再休提起。","从此水团圆，骨肉再和美。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-1920","tags":[]},{"id":"poem-33eb7ea76a9754faec3ef1e6","title":"小苑春望宫池柳色","author":"沈回","dynasty":"唐","verses":["今来游上苑，春染柳条轻。","濯濯方含色，依依若有情。","分行临曲沼，先发媚重城。","拂水枝偏弱，摇风丝已生。","变黄随淑景，吐翠逐新晴。","伫立徒延首，裴回欲寄诚。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-8b5e6994-a85a-4235-b84a-1d4f24ee0aa1","tags":[]},{"id":"poem-33f245d52c39565d19fefd12","title":"九日同诸公殊俗之作","author":"马云奇","dynasty":"唐","verses":["一人歌唱数人啼，拭泪相看意转迷。","不见书传清（青）海北，只知魂断陇山西。","登高乍似云霄近，寓目仍惊草树低。","菊酒何须频劝酌，自然心醉已如泥。","（太常妻曰一日不斋醉如泥）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-dc2e95ed-3e49-42cc-94dc-aa3f305ae76e","tags":[]},{"id":"poem-33f77ed6af6a9a300bdb4f2c","title":"横吹曲辞 陇头水 一","author":"僧皎然","dynasty":"唐","verses":["陇头心欲绝，陇水不堪闻。","碎影摇枪垒，寒声咽帐军。","素从盐海积，绿带柳城分。","日落天边望，逶迤入塞云。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-d531f315-bcc5-45b6-af4d-8752eef92780","tags":[]},{"id":"poem-33f8e466f8393e0e8fbc52da","title":"长相思","author":"李白","dynasty":"唐","verses":["长相思，在长安，络纬秋啼金井阑。","微霜凄凄簟色寒，孤灯不明思欲绝。","卷帷望月空长叹，美人如花隔云端。","上有青冥之长天，下有渌水之波澜。","天长路远魂飞苦，梦魂不到关山难。","长相思，摧心肝。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-3c1693fc-f4e6-43b7-a66f-6379c3a26eef","tags":["唐诗三百首","思念","杂曲歌辞","乐府","伤怀"]},{"id":"poem-34003ced0b882cd4651f950d","title":"游中梁山","author":"于邺","dynasty":"唐","verses":["僻地好泉石，何人曾陆沈。","不知青嶂外，更有白云深。","因此见乔木，几回思旧林。","殷勤猨与鸟，唯我独何心。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-ddc3beab-051a-4dae-9f5b-3304bc310423","tags":[]},{"id":"poem-3401955b212c3d51f4035804","title":"秋日翠微宫","author":"太宗皇帝","dynasty":"唐","verses":["秋光凝翠岭，凉吹肃离宫。","荷疎一盖缺，树冷半帷空。","侧阵移鸿影，圆花钉菊丛。","摅怀俗尘外，高眺白云中。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-fbb8a283-d6a5-4fc0-9fc3-33e422157b3f","tags":[]},{"id":"poem-34061580b38fe92073802fdd","title":"郊庙歌辞 汉宗庙乐舞辞 章庆舞","author":"张昭","dynasty":"唐","verses":["罘罳晓唱鸡人，三牲八簋斯陈。","雾集瑶阶琐闼，香生绮席华茵。","珠佩貂珰熠爚，羽旄干戚纷纶。","酌鬯既终三献，凝旒何止千春。","阿阁长栖彩凤，郊宫叠奏祥麟。","赤伏英灵未泯，玄圭运祚重新。","玉斝牺樽潋滟，龙旗凤辖逡巡。","瞻望月游冠冕，犹疑苍野回轮。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-792ab2c6-7baf-427b-bccf-e9e58537de8e","tags":[]},{"id":"poem-340e22a75c5e2226d8cc6c2e","title":"笑和尚","author":"杨景贤","dynasty":"元","verses":["二郎神神通广，五显圣驱兵将。","顿剑摇环显出那英雄相，一路上保护唐三藏。","轰雷掣电从天降，压伏定魔王。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-10123","tags":[]},{"id":"poem-341367d3b44a41a21d749dcc","title":"过当涂","author":"米芾","dynasty":"宋","verses":["鸥鹭依寒水，蒹葭静晚风。","烟光秋雨细，树色碧山重。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-07de35b1-2bb7-4da6-a1da-bebf8fa105eb","tags":[]},{"id":"poem-341d6d0b6da068b474855034","title":"同前","author":"萧德祥《小孙屠》","dynasty":"元","verses":["娘休虑，且宽心，何必自伤情。","(旦)虽然出去便回程，房儿里好凄清。","长叹两三声，它热如火我冷如冰。","(旦)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8636","tags":[]},{"id":"poem-3431717e868e5e8a0967c361","title":"伏闻令公疾愈对见延英因有贺诗远封投献","author":"薛逢","dynasty":"唐","verses":["吉语云云海外传，令公疾愈起朝天。","皇风再扇寰区内，人镜重开日月边。","光启四门通寿域，深疏万顷溉情田。","陪臣自讶迷津久，愿识方舟济巨川。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-a0f26ab9-6bb2-4715-98b7-5d5db8e6c99e","tags":[]},{"id":"poem-3431dfc3f7fabf004c57bd3f","title":"浣溪沙·依约残眉理旧黄","author":"张泌","dynasty":"五代","verses":["依约残眉理旧黄，翠鬟抛掷一簪长，暖风晴日罢朝妆。","闲折海棠看又捻，玉纤无力惹余香，此情谁会倚斜阳。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-4-juan.json#record-30","tags":[]},{"id":"poem-343894cac896f46bcc9c8402","title":"煞","author":"杨景贤","dynasty":"元","verses":["不知俺家告着他，他家告着俺？哥哥回去除了铁窨。","(行者云)你父母好善么？(裴女唱)俺爷平生好善常存性，俺娘从小看经不出音。","抬举得我如花锦，今日猪生狗活，兔扰狐侵。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-4512","tags":[]},{"id":"poem-343af3b7e17817eee06ba6bd","title":"蹋莎行・踏莎行·润玉笼绡","author":"吴文英","dynasty":"宋","verses":["润玉笼绡，檀樱倚扇。","绣圈犹带脂香浅。","榴心空叠舞裙红，艾枝应压愁鬟乱。","午梦千山，窗阴一箭。","香瘢新褪红丝腕。","隔江人在雨声中，晚风菰叶生秋怨。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-83","tags":["宋词三百首"]},{"id":"poem-343f29ff83aef8e260d57023","title":"挽于湖","author":"施士衡","dynasty":"宋","verses":["涌泉词笔坐中惊，天付斯文以道鸣。","独步蟾宫丹桂选，濡毫纶阁紫微清。","绝弦恸哭人琴丧，埋玉凄凉柱石倾。","一见那知成永别，重来天路问骑鲸。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-1380750c-59b1-48bf-a002-e739436d0f66","tags":[]},{"id":"poem-3444bce59a9e5e832dedffab","title":"远寺钟","author":"司空曙","dynasty":"唐","verses":["杳杳疎钟发，因风清复引。","中宵独听之，似与东林近。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-9649f4dc-e18d-4b00-bb8c-018e0d725b03","tags":[]},{"id":"poem-3445ea701b976922d8509669","title":"秋夜巫山","author":"乔备","dynasty":"唐","verses":["巫峡徘徊雨，阳台潭[一]荡云。","江山空窈窕，朝暮自氛氲。","萤色寒秋露，猿啼清夜闻。","唯怜梦魂远，肠断思纷纷。","（[一]俞云：「『潭』当作『澹』。","」刘云：「潭荡双声字。","」）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-00809229-fe6e-48c6-9783-38a1cab1dfe1","tags":[]},{"id":"poem-344a5994d471d5955ca7c5a0","title":"句","author":"陈知柔","dynasty":"宋","verses":["木落洞庭秋。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-6412bde5-9e13-4a90-9b79-434d7fd51628","tags":["洞庭湖"]},{"id":"poem-344f80e4b599c655d26b9d9e","title":"千秋岁·郁葱佳气","author":"黄公度","dynasty":"宋","verses":["郁葱佳气。","天降麒麟瑞。","回首处，江城外。","一麾遗爱在，万口欢声沸。","人乍远，危楼目断天无际。","五马徘徊地。","春色随归旆。","寿水绿，壶山翠。","风轻香篆直，日暖歌喉脆。","椒觞举，人人尽祝千秋岁。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-432","tags":[]},{"id":"poem-3454159dd7a3327cebf83db7","title":"前腔","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["［丑］哥哥听咨启，不必恁忧疑。","我邻居孙官人，赴选近回归。","他在京必知事体，问他音信，便知端的。","［外］无由去他宅里，你可令人请来问个详细。","［净上］日里莫说人，夜里莫说鬼。","方才说小子，小子便来至。","［末］未相邀，准来请你？［净］我在戏房中听得。","［末］这科诨休要提，且与东人相见施礼。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8187","tags":[]},{"id":"poem-346090ff2b3ae069fc40334e","title":"念奴娇·水枫叶下","author":"仲殊","dynasty":"宋","verses":["水枫叶下，乍湖光清浅。","凉生商素。","西帝宸游罗翠盖，拥出三千宫女。","绛采娇春，铅华掩昼，占断鸳鸯浦。","歌声摇曳，浣沙人在何处。","别岸孤袅一枝，广寒宫殿，冷落栖愁苦。","雪艳冰肌羞淡泊，偷把胭脂匀注。","媚脸笼霞，芳心泣露，不肯为云雨。","金波影里，为谁长恁凝伫。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-900","tags":[]},{"id":"poem-3476b245e10911695d3df4de","title":"江城子·极浦烟消水鸟飞","author":"牛峤","dynasty":"五代","verses":["极浦烟消水鸟飞，离筵分首时，送金卮。","渡口杨花，狂雪任风吹。","日暮天空波浪急，芳草岸，雨如丝。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-4-juan.json#record-26","tags":[]},{"id":"poem-3477b5198d7796d73484f279","title":"所居即事六首（原注：丹阳闲居寄郑明府如范上人。） 其一","author":"张祜","dynasty":"唐","verses":["南下丹阳一水湾，陋居瓢饮是希颜。","来为野鸟入春郭，去作溪云归夜山。","蓬鬓已衰言必贱，竹门虽立意无关。","陶潜惠远如相爱，朝访遗民暮却还。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-fbf4e269-503d-4bf9-8e21-a0958f3aa92a","tags":[]},{"id":"poem-347d9b7cface7bdae1096816","title":"虞美人·春花秋月何时了","author":"李煜","dynasty":"五代","verses":["春花秋月何时了，往事知多少？","小楼昨夜又东风，故国不堪回首月明中。","雕栏玉砌应犹在，只是朱颜改。","问君能有几多愁？恰似一江春水向东流。"],"enabled":true,"collection":"南唐二主词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/nantang/poetrys.json#record-4","tags":[]},{"id":"poem-347e17a478a36f318fd0db25","title":"颂古七十六首  其三四","author":"释士珪","dynasty":"宋","verses":["老僧正在东司上，不将佛法为人说。","一般屎臭旃檀香，父子之机俱漏泄。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-f952d8d0-7f91-48f2-88c6-a76673b434a4","tags":[]},{"id":"poem-3489a16a8438a4d44f91d328","title":"踏莎行·万水千山","author":"向","dynasty":"宋","verses":["万水千山，两头三绪。","凭高望断迢迢路。","钱塘江上客归迟，落花流水青春暮。","步步金莲，朝朝琼树。","目前都是伤心处。","飞鸿过尽没书来，梦魂依旧阳台雨。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-186","tags":["钱塘江"]},{"id":"poem-349b0072fca2dd20b50e25dc","title":"梁谿八咏 怡亭","author":"李纲","dynasty":"宋","verses":["缥缈危亭枕曲池，红粧翠羽自参差。","晚凉小饮谁同醉，定把圆荷当屈巵。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-702ca3f9-03b5-459c-9219-f975cc9750e8","tags":[]},{"id":"poem-34b14ae6193c34d5c09c213b","title":"红林擒近·晓起山光惨","author":"方千里","dynasty":"宋","verses":["晓起山光惨，晚来花意寒。","映月衣纤缟，因风佩琅玕。","三弄江梅听彻，几点岸柳飘残。","宛然舞曲初翻。","帘影卷波澜。","把酒同唤醒，促膝小留欢。","清狂痛饮，能消多少杯盘。","况人生如寄，相逢半老，岁华休作容易看。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-547","tags":[]},{"id":"poem-34b1574c4dd0aa885b09c2b0","title":"朝中措·平生此地几经过","author":"向","dynasty":"宋","verses":["平生此地几经过。","家近奈情何。","长记月斜风劲，小舟犹渡烟波。","而今老大，欢消意减，只有愁多。","不似旧时心性，夜长听彻渔歌。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-203","tags":[]},{"id":"poem-34b8d60b4d0e823445c34c27","title":"秋雨叹三首 三","author":"杜甫","dynasty":"唐","verses":["长安布衣谁比数，反鏁衡门守环堵。","老夫不出长蓬蒿，穉子无忧走（一作「奏」）风雨。","雨声飕飕催早寒，胡雁翅湿高飞难。","秋来未曾（一作「省」）见白日，埿污后（一作「厚」）土何时干？"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-9c725632-fe02-4fc7-b443-9410da36c7e5","tags":[]},{"id":"poem-34bb589ea8ee995250ca4c1a","title":"秋日旅舍别司空文明","author":"李端","dynasty":"唐","verses":["凉风飒穷巷，秋思满高云。","吏隐俱不就，此心仍别君。","素怀宗淡泊，羁旅念功勋。","转忆西林寺，江声月下闻。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-4d79a7f2-2e3c-496a-b9bd-9f778aee26ee","tags":[]},{"id":"poem-34c1b457974c64036d67fea0","title":"读贾太傅传  其一","author":"释居简","dynasty":"宋","verses":["诸老先生总未言，一言中的已先闻。","守成天子恭沉默，不妬多功重少文。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-6bd58be6-69ab-456f-8227-d1c010a45571","tags":[]},{"id":"poem-34c8c8ec25b1d4987d0fe4e5","title":"上鼓山国师偈兼请师和之（题拟）","author":"王十八郎","dynasty":"唐","verses":["无形无本亦无名，日用驱驱不暂停。","对面向人多不识，纵横自在转分明。","权时来寄君家宅，万种千般是事能。","认取当来真本性，一时抛弃事皆行。","（同前。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-355a1ae2-524c-4ebb-991f-a437ea1902d3","tags":[]},{"id":"poem-34cbf9ccdbe833d1216c7a4e","title":"偈颂（幷序○序为南岳齐己撰） 十八","author":"居遁","dynasty":"唐","verses":["了得心源处处安，何须终日对林峦。","玉向火中烧转润，莲华在水叶长干。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-d69e9b23-4f01-441b-a45a-0d43e41ef7eb","tags":["衡山"]},{"id":"poem-34d91045d21afaf61f10e4d4","title":"和欧阳永叔少师会老唱和诗三首 寄汝阴少师","author":"苏颂","dynasty":"宋","verses":["得时行道贵知终，猛退如公世罕逢。","掷弃浮名同敝屣，保全高节似寒松。","文章千古追谟诰，勋业三朝镂鼎钟。","见说新堂频燕会，故时宾客定相容。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-b3114650-68bd-468b-9dd4-4bf9eca6e7ed","tags":[]},{"id":"poem-34dd800feeed7dce3d3480f1","title":"吊元鲁山 三","author":"孟郊","dynasty":"唐","verses":["君子不自蹇，鲁山蹇有因。","苟含天地秀，皆是天地身。","天地蹇既甚，鲁山道莫伸。","天地气不足，鲁山食更贫。","始知补元化，竟须得贤人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-e5639382-92ac-4d40-a3cd-2196c3843182","tags":[]},{"id":"poem-34e65f3e1ee66205aa7e780c","title":"巫山一段云·古庙依青嶂","author":"李珣","dynasty":"五代","verses":["古庙依青嶂，行宫枕碧流。","水声山色锁妆楼，往事思悠悠。","云雨朝还暮，烟花春复秋。","啼猿何必近孤舟，行客自多愁。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-x-juan.json#record-22","tags":[]},{"id":"poem-34ef101a1478c78781808ef0","title":"月出","author":"佚名","dynasty":"先秦","verses":["月出皎兮。佼人僚兮。舒窈纠兮。劳心悄兮。","月出皓兮。佼人懰兮。舒忧受兮。劳心慅兮。","月出照兮。佼人燎兮。舒夭绍兮。劳心惨兮。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-142","tags":[]},{"id":"poem-34ef8da40046dc386a271b9a","title":"青玉案·一年春事都来几","author":"无名氏","dynasty":"宋","verses":["一年春事都来几。","早过了、三之二。","绿暗红嫣浑可事。","绿杨庭院，暖风帘幕，有个人憔悴。","买花载酒长安市。","又争似家山见桃李。","不枉东风吹客泪，相思难表，梦魂无据，惟有归来是。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-77","tags":["宋词三百首"]},{"id":"poem-34efbf259c2e5c8b1dc521af","title":"酒醒","author":"崔道融","dynasty":"唐","verses":["酒醒拨剔残灰火，多少凄凉在此中。","炉畔自斟还自醉，打窗深夜雪兼风。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-9f3e021b-7f42-4a98-b8da-1cd77f15ba57","tags":[]},{"id":"poem-34f92d84165a4f767f403ac7","title":"赋得石梁泉送崔逵","author":"皎然","dynasty":"唐","verses":["架石通霞壁，悬崖散碧沙。","天晴虹影渡，风细练文斜。","举陟幽期阻，沿洄客意赊。","河梁非此路，别恨亦无涯。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-745f741a-151f-48c7-94c9-bb8a314c197e","tags":[]},{"id":"poem-3501f603d72ec7a65885226d","title":"下雪潭雪浪亭","author":"陈岩","dynasty":"宋","verses":["潭面摇光媚日华，水文倒影射簷牙。","倚阑如在云霄上，俯看萦风万雪花。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-7ce1bd39-d617-4464-99bf-2d4d766cedc4","tags":[]},{"id":"poem-350b734016885aee32cdb7de","title":"萧宅二三子赠答诗二十首 客赠石","author":"卢仝","dynasty":"唐","verses":["竹下青莎中，细长三四片。","主人虽不归，长见主人面。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-59e3f594-bbfb-4574-ab2e-69b415d8468c","tags":[]},{"id":"poem-3515e2badb2fb7f8b7aa6173","title":"和周侍御买剑","author":"曹唐","dynasty":"唐","verses":["将军溢价买吴钩，要与中原静寇讐。","试挂窗前惊电转，略抛床下怕泉流。","青天露拔云霓泣，黑地潜擎鬼魅愁。","见说夜深星斗畔，等闲期尅月支头。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-a963f58e-ac9f-498d-96fb-6e15ec249d80","tags":[]},{"id":"poem-351b8ac59b0d9a4dd29ca320","title":"人日寄杜二拾遗","author":"高适","dynasty":"唐","verses":["人日题诗寄草堂，遥怜故人思故乡。","柳条弄色不忍见，梅花满枝空断肠。","身在远藩无所预，心怀百忧复千虑。","今年人日空相忆，明年人日知何处。","一卧东山三十春，岂知书劒老风尘。","龙钟还忝二千石，愧尔东西南北人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-a7318ace-183f-44e8-9704-3fceabe908be","tags":["思念"]},{"id":"poem-351fe72444834635417d3413","title":"水调歌头·天地孕冲气","author":"侯置","dynasty":"宋","verses":["天地孕冲气，霜雪实嘉平。","粹然经世材具，应为圣时生。","妙处为仁受用。","颠倒纵横无壅。","一笑泮春冰。","袖手无一语，四海已倾情。","紫岩老，游戏事，悟诚明。","当年夷夏高仰，玉振更金声。","家有渊骞高第。","可但闻诗闻礼。","衣钵要相承。","周扆绚馀彩，商鼎味新羹。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-999","tags":[]},{"id":"poem-3528d97f43b62f866b0129e1","title":"小星","author":"佚名","dynasty":"先秦","verses":["嘒彼小星，三五在东。肃肃宵征，夙夜在公。寔命不同！","嘒彼小星，维参与昴。肃肃宵征，抱衾与裯。寔命不犹！"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-20","tags":[]},{"id":"poem-353185feff2c9336ae190271","title":"山居八咏 八","author":"常达","dynasty":"唐","verses":["祖祖唯心旨，春融日正长。","霜轻莎草绿，风细药苗香。","月满真如净，花开觉树芳。","庭前莺啭处，时听语圆常。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-cf25e8c0-10fb-4379-b9ed-6e91f43267c2","tags":[]},{"id":"poem-3534b59165e5fbae490f2676","title":"密云","author":"纳兰性德","dynasty":"清","verses":["白檀山下水声秋，地踞潮河最上流。","日暮行人寻堠馆，凉砧一片古檀州。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-251","tags":[]},{"id":"poem-3535f29bb16474aa7a41adfc","title":"宁国奉圣寺有许浑旧题","author":"释居简","dynasty":"宋","verses":["题擅玉台宾，山名益著闻。","禽珍腾逸响，草异荐奇芬。","壁可曾留锡，簷栖欲去云。","尘嚣避三舍，不度碧溪𣸣。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-d2b99908-7227-4b04-a30e-2413673bf68e","tags":[]},{"id":"poem-353666794d16ff726f5610c6","title":"别柳将军庙","author":"蒋静","dynasty":"宋","verses":["梦事虽非实，将军默有灵。","旧祠从此焕，古桧蔚然青。","甲马宵中见，琴堂卧正冥。","留诗非志怪，三五扣神扃。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-69aa1c36-7d10-402a-bf5d-0ad2d363be8c","tags":[]},{"id":"poem-354672a154351724dbb480ed","title":"和都城春雪","author":"华镇","dynasty":"宋","verses":["六花飞压九街尘，应讶人间未觉春。","天上楼台银作屋，云中车辂玉为轮。","三秋狼戾盈仓兆，万国欢呼击壤辰。","寂寞袁门烟火冷，未知谁是扣关人。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-d1c6600e-7469-4855-b53d-91221be560bf","tags":[]},{"id":"poem-35481a79644a729c21856e03","title":"和令狐侍郎郭郎中题项羽庙","author":"孟郊","dynasty":"唐","verses":["碧草凌古庙，清尘锁秋窗。","当时独宰割，猛志谁能降。","鼓气雷作敌，劒光电为双。","新悲徒自起，旧恨空浮江。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-92c87b6b-ce3d-4207-9182-c8b60acae2f6","tags":[]},{"id":"poem-3552b5ddf4f6991362d1f2e6","title":"和陶渊明二十首  其二","author":"陈造","dynasty":"宋","verses":["壮岁锐著述，瞢欲藏名山。","中间忽自哂，聒聒厌多言。","弃置杯中乐，雕锼耗岁年。","不知百岁后，何益空名传。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-20890e8f-783b-4587-8fc4-0a00c54cbdb1","tags":[]},{"id":"poem-3556123b34a4852162e0f2f6","title":"生查子·去年元夜时","author":"欧阳修","dynasty":"宋","verses":["去年元夜时，花市灯如昼。","月到柳梢头，人约黄昏后。","今年元夜时，月与灯依旧。","不见去年人，泪满春衫袖。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-624","tags":[]},{"id":"poem-355a359497006fda847cabba","title":"奉和韦侍御陪相公游开义五言六韵","author":"李德裕","dynasty":"唐","verses":["羊公追胜概，兹地暂逍遥。","风景同南岘，丹青见北朝。","石渠清夏气，高树激鲜飙。","念法珍禽集，闻轻醉象调。","偶分甘露味，偏觉众香饶。","为问毘城内，余薰几日销。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-f835c483-7870-4846-b4c7-138ec4af57d1","tags":[]},{"id":"poem-355b1b3201c12829cf567ed3","title":"临江仙·庭院深深深几许","author":"李清照","dynasty":"宋","verses":["庭院深深深几许，云窗雾阁春迟。","为谁憔悴损芳姿。","夜来清梦好，应是发南枝。","玉瘦檀轻无限恨，南楼羌管休吹。","浓香吹尽有谁知。","暖风迟日也，别到杏花肥。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-723","tags":[]},{"id":"poem-355dc91f54864ae047dda870","title":"于中好·小构园林寂不哗","author":"纳兰性德","dynasty":"清","verses":["小构园林寂不哗，疏篱曲径仿山家。","昼长吟罢风流子，忽听楸枰响碧纱。","添竹石，伴烟霞。","拟凭樽酒慰年华。","休嗟髀里今生肉，努力春来自种花。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-140","tags":[]},{"id":"poem-356036ac592a6e9f2759b081","title":"与诸同僚偶会赋八题 府庠小沼","author":"苏颂","dynasty":"宋","verses":["面向秦淮流，背枕清溪水。","当轩观未足，凿沼近可拟。","月明练光寒，风动漪涟起。","不用植菰蒲，惟将鉴容止。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-0612b620-cbf1-45c5-9927-bba8a9e60be9","tags":[]},{"id":"poem-35643f87148e22510952c367","title":"画堂春·小槽春酿香红","author":"史浩","dynasty":"宋","verses":["小槽春酿香红。","良辰飞盖相从。","主人着意在金钟。","茗碗作先容。","欲到醉乡深处，应须仗、两腋香风。","献酬高兴渺无穷。","归骑莫匆匆。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-174","tags":[]},{"id":"poem-35682a19affd54f950a92883","title":"生查子·东风不解愁","author":"纳兰性德","dynasty":"清","verses":["东风不解愁，偷展湘裙衩。","独夜背纱笼，影著纤腰画。","𦶟尽水沉烟，露滴鸳鸯瓦。","花骨冷宜香，小立樱桃下。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-7","tags":[]},{"id":"poem-3570ebcbca44399778c528d5","title":"招玉川子咏新文","author":"徐希仁","dynasty":"唐","verses":["清气宿我心，结为清泠音。","一夜吟不足，君来相和吟。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-658a51ea-a071-4fdb-b6f2-1d356b199e44","tags":[]},{"id":"poem-3578a733656f10790ac415dd","title":"九怀·思忠","author":"王褒","dynasty":"汉","verses":["登九灵兮游神，静女歌兮微晨。","悲皇丘兮积葛，众体错兮交纷。","贞枝抑兮枯槁，枉车登兮庆云。","感余志兮惨栗，心怆怆兮自怜。","驾玄螭兮北征，向吾路兮葱岭。","连五宿兮建旄，扬氛气兮为旌。","历广漠兮驰骛，览中国兮冥冥。","玄武步兮水母，与吾期兮南荣。","登华盖兮乘阳，聊逍遥兮播光。","抽库娄兮酌醴，援瓟瓜兮接粮。","毕休息兮远逝，发玉轫兮西行。","惟时俗兮疾正，弗可久兮此方。","寤辟摽兮永思，心怫郁兮内伤。"],"enabled":true,"collection":"楚辞","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/楚辞/chuci.json#record-44","tags":[]},{"id":"poem-357ae309cf66c1096ec65de1","title":"天作","author":"佚名","dynasty":"先秦","verses":["天作高山，大王荒之。彼作矣，文王康之。彼徂矣，岐有夷之行。子孙保之。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-269","tags":[]},{"id":"poem-357c55b393e07c020d938da7","title":"寻僧","author":"赵嘏","dynasty":"唐","verses":["斜日横窗起暗尘，水边门户闭闲春。","千竿竹里花枝动，只道无人似有人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-1362acd7-e6e8-4178-aac6-266cb346faf2","tags":[]},{"id":"poem-35805f91b399c6b87653c38c","title":"赤城六章章四句  其四","author":"释居简","dynasty":"宋","verses":["千里寿公，祷公寿康。","惠洽兆庶，日飞百觞。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-f4e83063-4fd8-4a1b-a613-b3ee8e405a6f","tags":[]},{"id":"poem-358b03d9c3ac2f07087fb7b4","title":"菩萨蛮 其八","author":"温庭筠","dynasty":"唐","verses":["牡丹花谢莺声歇，绿杨满院中庭月。","相忆梦难成，背窗灯半明。","翠钿金压脸，寂寞香闺掩。","人远泪阑干，燕飞春又残。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-1-juan.json#record-7","tags":[]},{"id":"poem-3591882e8f52f050a098fd71","title":"腊后感怀和光道韵","author":"华镇","dynasty":"宋","verses":["达人蔑视千钟禄，曲士惊谈五石瓢。","腊尽自怜春气近，月明谁念美人遥。","铅华次第开梅萼，金色依稀著柳条。","莫问阴山更阴处，数峰残雪未全销。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-0882b86b-e137-455a-9a75-687041e509ee","tags":[]}];
